window.CV_INDEX = [{"n":0.1,"f":"p1-images-as-tensors.html","ti":"Images as Tensors","lv":"Prerequisites","e":[{"t":"Pixels and channels","a":"s1-pixels-and-channels","k":"section"},{"t":"Three libraries, three answers","a":"s2-three-libraries-three-answers","k":"section"},{"t":"HWC to CHW: permute, not reshape","a":"s3-hwc-to-chw-permute-not-reshape","k":"section"},{"t":"uint8 arithmetic bites","a":"s4-uint8-arithmetic-bites","k":"section"},{"t":"Scaling and normalising","a":"s5-scaling-and-normalising","k":"section"},{"t":"Batches, and where to convert","a":"s6-batches-and-where-to-convert","k":"section"},{"t":"Check your understanding","a":"s7-check-your-understanding","k":"section"},{"t":"Preprocessing lab","a":"s6-batches-and-where-to-convert","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: one architecture, two preprocessing contracts","a":"s6-batches-and-where-to-convert","k":"topic"},{"t":"Common mistakes","a":"s6-batches-and-where-to-convert","k":"topic"},{"t":"Interview drill","a":"s6-batches-and-where-to-convert","k":"topic"},{"t":"PIL and scikit-image give RGB, OpenCV gives BGR, torchvision gives CHW. Know which one you used.","a":"s6-batches-and-where-to-convert","k":"fact"},{"t":"permute(2, 0, 1) moves the channel axis; reshape scrambles the image and took accuracy from 87.2% to 0%.","a":"s6-batches-and-where-to-convert","k":"fact"},{"t":"uint8 arithmetic wraps around: 200 + 100 is 44. Convert to float before computing with pixels.","a":"s6-batches-and-where-to-convert","k":"fact"},{"t":"Print the tensor’s min and max just before the model, and keep one known image with a known answer as a test.","a":"s6-batches-and-where-to-convert","k":"fact"}]},{"n":0.2,"f":"p2-pytorch-training-loop.html","ti":"PyTorch & the Training Loop","lv":"Prerequisites","e":[{"t":"Autograd: gradients you don’t derive","a":"s1-autograd-gradients-you-don-t-derive","k":"section"},{"t":"Modules, parameters and optimisers","a":"s2-modules-parameters-and-optimisers","k":"section"},{"t":"The loop","a":"s3-the-loop","k":"section"},{"t":"The learning rate decides everything","a":"s4-the-learning-rate-decides-everything","k":"section"},{"t":"Five one-line bugs","a":"s5-five-one-line-bugs","k":"section"},{"t":"Overfit one batch first","a":"s6-overfit-one-batch-first","k":"section"},{"t":"Check your understanding","a":"s7-check-your-understanding","k":"section"},{"t":"Training loop lab","a":"s3-the-loop","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: PyTorch 2.0 changed what zero_grad() does","a":"s6-overfit-one-batch-first","k":"topic"},{"t":"Common mistakes","a":"s6-overfit-one-batch-first","k":"topic"},{"t":"Interview drill","a":"s6-overfit-one-batch-first","k":"topic"},{"t":"loss.backward() fills each parameter’s .grad with the chain rule; it matched the hand-derived gradient to 1.5 × 10⁻⁸.","a":"s6-overfit-one-batch-first","k":"fact"},{"t":"The loop is forward, loss, zero_grad , backward , step , every batch, with a fresh shuffle every epoch.","a":"s6-overfit-one-batch-first","k":"fact"},{"t":"Missing zero_grad , a missing step and class-sorted batches each gave 10%; double softmax quietly cost 3 points.","a":"s6-overfit-one-batch-first","k":"fact"}]},{"n":0.3,"f":"p3-colour-gamma-and-formats.html","ti":"Colour Spaces, Gamma & Image Formats","lv":"Prerequisites","e":[{"t":"One colour, five encodings","a":"s1-one-colour-five-encodings","k":"section"},{"t":"Gamma: the stored number is not the light","a":"s2-gamma-the-stored-number-is-not-the-light","k":"section"},{"t":"JPEG: what quality costs","a":"s3-jpeg-what-quality-costs","k":"section"},{"t":"Colour and orientation, measured","a":"s4-colour-and-orientation-measured","k":"section"},{"t":"EXIF orientation: the sideways photo","a":"s5-exif-orientation-the-sideways-photo","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Format lab","a":"s5-exif-orientation-the-sideways-photo","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: the image CDN that resizes for you","a":"s5-exif-orientation-the-sideways-photo","k":"topic"},{"t":"Common mistakes","a":"s5-exif-orientation-the-sideways-photo","k":"topic"},{"t":"Interview drill","a":"s5-exif-orientation-the-sideways-photo","k":"topic"},{"t":"The same colour is RGB, BGR, YCbCr or HSV depending on the job; greyscale weights green most (0.587).","a":"s5-exif-orientation-the-sideways-photo","k":"fact"},{"t":"Re-saving a JPEG at its original quality is almost lossless; at a different quality it loses a little more each time.","a":"s5-exif-orientation-the-sideways-photo","k":"fact"}]},{"n":0.4,"f":"p4-geometry-and-transforms.html","ti":"Geometry: Coordinates & Transforms","lv":"Prerequisites","e":[{"t":"Pixel coordinates","a":"s1-pixel-coordinates","k":"section"},{"t":"Homogeneous coordinates","a":"s2-homogeneous-coordinates","k":"section"},{"t":"Homographies: flattening a page","a":"s3-homographies-flattening-a-page","k":"section"},{"t":"Resampling: which pixel, and what value","a":"s4-resampling-which-pixel-and-what-value","k":"section"},{"t":"Boxes move with their images","a":"s5-boxes-move-with-their-images","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Transform lab","a":"s2-homogeneous-coordinates","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: the half-pixel shift in segmentation masks","a":"s5-boxes-move-with-their-images","k":"topic"},{"t":"Common mistakes","a":"s5-boxes-move-with-their-images","k":"topic"},{"t":"Interview drill","a":"s5-boxes-move-with-their-images","k":"topic"},{"t":"Image y points down; arrays are [y, x]; sizes are often (W, H). Know which convention each call uses.","a":"s5-boxes-move-with-their-images","k":"fact"},{"t":"align_corners changes where pixel centres sit; it must match between images, masks and frameworks.","a":"s5-boxes-move-with-their-images","k":"fact"},{"t":"A homography from four point pairs flattens a photographed plane; divide by w to get the pixel.","a":"s5-boxes-move-with-their-images","k":"fact"},{"t":"Antialiased and plain bilinear resizes differ by about 4 grey levels per pixel; pick one for training and serving.","a":"s5-boxes-move-with-their-images","k":"fact"}]},{"n":0.5,"f":"p5-classical-filtering.html","ti":"Classical Filtering: Blur, Edges & Kernels","lv":"Prerequisites","e":[{"t":"A kernel sliding over an image","a":"s1-a-kernel-sliding-over-an-image","k":"section"},{"t":"The classic kernels","a":"s2-the-classic-kernels","k":"section"},{"t":"Correlation or convolution?","a":"s3-correlation-or-convolution","k":"section"},{"t":"Separable kernels","a":"s4-separable-kernels","k":"section"},{"t":"What happens at the border","a":"s5-what-happens-at-the-border","k":"section"},{"t":"Noise decides the filter","a":"s6-noise-decides-the-filter","k":"section"},{"t":"Check your understanding","a":"s7-check-your-understanding","k":"section"},{"t":"Kernel playground","a":"s2-the-classic-kernels","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: Canny edges in a document scanner","a":"s6-noise-decides-the-filter","k":"topic"},{"t":"Common mistakes","a":"s6-noise-decides-the-filter","k":"topic"},{"t":"Interview drill","a":"s6-noise-decides-the-filter","k":"topic"},{"t":"A filter is a small grid of weights slid over the image: a weighted sum at every position.","a":"s6-noise-decides-the-filter","k":"fact"},{"t":"Weights summing to 1 keep brightness (blur, sharpen); summing to 0 respond only to change (edges), with signed outputs.","a":"s6-noise-decides-the-filter","k":"fact"},{"t":"Rank-1 kernels are separable: 2k instead of k² multiplies. A 31 × 31 Gaussian ran in 1.51 ms instead of 12.53 ms.","a":"s6-noise-decides-the-filter","k":"fact"},{"t":"Zero padding darkens the border (68.7 against a true 124.4 for a 9 × 9 blur); reflect or replicate avoid it.","a":"s6-noise-decides-the-filter","k":"fact"},{"t":"Match the filter to the noise: Gaussian blur for grain (30.3 dB), median for salt and pepper (33.9 dB).","a":"s6-noise-decides-the-filter","k":"fact"}]},{"n":0.6,"f":"p6-loading-image-data.html","ti":"Loading Image Data Fast","lv":"Prerequisites","e":[{"t":"Dataset and DataLoader","a":"s1-dataset-and-dataloader","k":"section"},{"t":"What one image costs","a":"s2-what-one-image-costs","k":"section"},{"t":"How many workers?","a":"s3-how-many-workers","k":"section"},{"t":"Is my run data-bound?","a":"s4-is-my-run-data-bound","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"Input pipeline planner","a":"s2-what-one-image-costs","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: fast ImageNet training was a data-loading problem","a":"s4-is-my-run-data-bound","k":"topic"},{"t":"Common mistakes","a":"s4-is-my-run-data-bound","k":"topic"},{"t":"Interview drill","a":"s4-is-my-run-data-bound","k":"topic"},{"t":"A Dataset returns one item; a DataLoader batches, shuffles and runs worker processes that prefetch.","a":"s4-is-my-run-data-bound","k":"fact"},{"t":"Workers scale throughput almost linearly: 260 images/s with none, 3,939 with eight, 5,077 with twelve.","a":"s4-is-my-run-data-bound","k":"fact"},{"t":"Return uint8 and normalise on the GPU: 3,939 → 6,357 images/s, and 4× smaller batches to copy.","a":"s4-is-my-run-data-bound","k":"fact"},{"t":"Stop adding workers once the loader beats the GPU: ResNet-50 needs about 970 images/s here, ResNet-18 about 2,860.","a":"s4-is-my-run-data-bound","k":"fact"},{"t":"Check for starvation by comparing the real loop with synthetic data on the GPU, and by timing waits on the loader.","a":"s4-is-my-run-data-bound","k":"fact"}]},{"n":0.7,"f":"p7-losses-and-metrics.html","ti":"Losses & Metrics for Classifiers","lv":"Prerequisites","e":[{"t":"Logits, softmax and its overflow","a":"s1-logits-softmax-and-its-overflow","k":"section"},{"t":"Cross-entropy: the loss","a":"s2-cross-entropy-the-loss","k":"section"},{"t":"Accuracy, top-k and the confusion matrix","a":"s3-accuracy-top-k-and-the-confusion-matrix","k":"section"},{"t":"Precision, recall and F1","a":"s4-precision-recall-and-f1","k":"section"},{"t":"Thresholds and the accuracy paradox","a":"s5-thresholds-and-the-accuracy-paradox","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Metrics lab","a":"s3-accuracy-top-k-and-the-confusion-matrix","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: choosing the threshold for a content filter","a":"s5-thresholds-and-the-accuracy-paradox","k":"topic"},{"t":"Common mistakes","a":"s5-thresholds-and-the-accuracy-paradox","k":"topic"},{"t":"Interview drill","a":"s5-thresholds-and-the-accuracy-paradox","k":"topic"},{"t":"Accuracy 77.7%, top-3 95.1%: report both when classes are similar.","a":"s5-thresholds-and-the-accuracy-paradox","k":"fact"},{"t":"The confusion matrix shows which mistakes: cat recall 0.49, dog precision 0.61, because furry animals go to “dog”.","a":"s5-thresholds-and-the-accuracy-paradox","k":"fact"},{"t":"A rule that never says “cat” is 90% accurate here. Always give the base rate with accuracy.","a":"s5-thresholds-and-the-accuracy-paradox","k":"fact"}]},{"n":0.8,"f":"p8-gpu-memory-and-throughput.html","ti":"GPU Memory & Throughput for Images","lv":"Prerequisites","e":[{"t":"Where the memory goes","a":"s1-where-the-memory-goes","k":"section"},{"t":"Memory follows a straight line","a":"s2-memory-follows-a-straight-line","k":"section"},{"t":"bf16 and channels-last","a":"s3-bf16-and-channels-last","k":"section"},{"t":"Inference: latency vs throughput","a":"s4-inference-latency-vs-throughput","k":"section"},{"t":"Out of memory","a":"s5-out-of-memory","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Memory planner","a":"s2-memory-follows-a-straight-line","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: high-resolution segmentation on a single GPU","a":"s5-out-of-memory","k":"topic"},{"t":"Common mistakes","a":"s5-out-of-memory","k":"topic"},{"t":"Interview drill","a":"s5-out-of-memory","k":"topic"},{"t":"Training memory = fixed (weights, gradients, optimiser state) + activations; for vision, activations dominate.","a":"s5-out-of-memory","k":"fact"},{"t":"ResNet-50 peak memory was 372 MB + 42.4 MB per 224 × 224 image, a straight line that also predicted every resolution.","a":"s5-out-of-memory","k":"fact"},{"t":"Memory scales with batch × side²: 640 px at batch 32 needed as much as 224 px at batch 256.","a":"s5-out-of-memory","k":"fact"},{"t":"bf16 + channels-last trained 2.1× faster than fp32 at 55% of the memory; channels-last alone in fp32 was 4.7× slower.","a":"s5-out-of-memory","k":"fact"}]},{"n":1,"f":"01-what-computer-vision-is.html","ti":"What Computer Vision Is","lv":"Beginner","e":[{"t":"The tasks","a":"s1-the-tasks","k":"section"},{"t":"Three models, one photo","a":"s2-three-models-one-photo","k":"section"},{"t":"What comes back, and what it costs","a":"s3-what-comes-back-and-what-it-costs","k":"section"},{"t":"Where models fail","a":"s4-where-models-fail","k":"section"},{"t":"What this course builds","a":"s5-what-this-course-builds","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Three models, seven photos","a":"s2-three-models-one-photo","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: searching a photo library","a":"s4-where-models-fail","k":"topic"},{"t":"Common mistakes","a":"s5-what-this-course-builds","k":"topic"},{"t":"Interview drill","a":"s5-what-this-course-builds","k":"topic"},{"t":"Classification answers “what”, detection “what and where”, segmentation “which pixels”; generation runs the other way.","a":"s5-what-this-course-builds","k":"fact"},{"t":"A model can only answer with its own labels: ImageNet has 1,000 classes but no person, COCO has 80, VOC has 20.","a":"s5-what-this-course-builds","k":"fact"},{"t":"Each model has its own preprocessing and postprocessing; the network is the middle of a pipeline.","a":"s5-what-this-course-builds","k":"fact"},{"t":"Softmax confidence is not a measure of “known vs unknown”: a galaxy field became “bubble” at 45.7%.","a":"s5-what-this-course-builds","k":"fact"}]},{"n":2,"f":"02-convolutions-in-depth.html","ti":"Convolutions in Depth","lv":"Beginner","e":[{"t":"Many channels in, many channels out","a":"s1-many-channels-in-many-channels-out","k":"section"},{"t":"Stride, padding, dilation and the output size","a":"s2-stride-padding-dilation-and-the-output-s","k":"section"},{"t":"Writing it from scratch, twice","a":"s3-writing-it-from-scratch-twice","k":"section"},{"t":"FLOPs, and what cuDNN does better","a":"s4-flops-and-what-cudnn-does-better","k":"section"},{"t":"Receptive fields","a":"s5-receptive-fields","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Convolution explorer","a":"s4-flops-and-what-cudnn-does-better","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: dilated convolutions in segmentation","a":"s5-receptive-fields","k":"topic"},{"t":"Common mistakes","a":"s5-receptive-fields","k":"topic"},{"t":"Interview drill","a":"s5-receptive-fields","k":"topic"},{"t":"A conv layer’s weights are (C_out, C_in, K, K): Conv2d(64, 128, 3) has 73,856 parameters, used at every position.","a":"s5-receptive-fields","k":"fact"},{"t":"Output size = (H + 2p − d(K − 1) − 1) // s + 1; it matched PyTorch on 2,000 random configurations.","a":"s5-receptive-fields","k":"fact"},{"t":"im2col turns convolution into one matrix multiply, at the cost of a K²-times-larger copy of the input (49 MB → 441 MB).","a":"s5-receptive-fields","k":"fact"}]},{"n":3,"f":"03-building-a-cnn.html","ti":"Building a CNN","lv":"Beginner","e":[{"t":"Conv, ReLU, pool","a":"s1-conv-relu-pool","k":"section"},{"t":"CNN vs MLP on the same pixels","a":"s2-cnn-vs-mlp-on-the-same-pixels","k":"section"},{"t":"Equivariance, invariance and the shift test","a":"s3-equivariance-invariance-and-the-shift-te","k":"section"},{"t":"Check your understanding","a":"s4-check-your-understanding","k":"section"},{"t":"CNN vs MLP lab","a":"s2-cnn-vs-mlp-on-the-same-pixels","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: LeNet reading cheques","a":"s3-equivariance-invariance-and-the-shift-te","k":"topic"},{"t":"Common mistakes","a":"s3-equivariance-invariance-and-the-shift-te","k":"topic"},{"t":"Interview drill","a":"s3-equivariance-invariance-and-the-shift-te","k":"topic"},{"t":"A CNN repeats conv → (BN) → ReLU and downsamples between blocks: spatial size falls while channels rise.","a":"s3-equivariance-invariance-and-the-shift-te","k":"fact"},{"t":"Parameters gather in the late, wide layers; compute in the early, high-resolution ones.","a":"s3-equivariance-invariance-and-the-shift-te","k":"fact"},{"t":"At equal parameters the CNN scored 88.0% against 54.7% for an MLP; 13.7× more parameters lifted the MLP only to 59.7%.","a":"s3-equivariance-invariance-and-the-shift-te","k":"fact"},{"t":"Convolutions are equivariant; pooling and the head add only partial invariance. Random crops supply the rest.","a":"s3-equivariance-invariance-and-the-shift-te","k":"fact"}]},{"n":4,"f":"04-training-a-cnn.html","ti":"Training a CNN on CIFAR-10","lv":"Beginner","e":[{"t":"The dataset and the recipe","a":"s1-the-dataset-and-the-recipe","k":"section"},{"t":"Reading the curves","a":"s2-reading-the-curves","k":"section"},{"t":"Finding the learning rate","a":"s3-finding-the-learning-rate","k":"section"},{"t":"Batch size and the linear scaling rule","a":"s4-batch-size-and-the-linear-scaling-rule","k":"section"},{"t":"Overfitting on purpose","a":"s5-overfitting-on-purpose","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Training run explorer","a":"s2-reading-the-curves","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: training ImageNet in an hour","a":"s5-overfitting-on-purpose","k":"topic"},{"t":"Common mistakes","a":"s5-overfitting-on-purpose","k":"topic"},{"t":"Interview drill","a":"s5-overfitting-on-purpose","k":"topic"},{"t":"A 1.2M-parameter CNN reached 91.68% on CIFAR-10 in 47 s with SGD, one-cycle LR, crops, flips and weight decay.","a":"s5-overfitting-on-purpose","k":"fact"},{"t":"Read train and test curves together: close and poor is underfitting; a widening gap with flat test is overfitting.","a":"s5-overfitting-on-purpose","k":"fact"},{"t":"A factor-of-three LR sweep is cheap: 0.03 was best for 10 epochs; 1.0 and above diverged to 10%.","a":"s5-overfitting-on-purpose","k":"fact"},{"t":"Linear LR scaling helped below batch 256 and broke above it; batch 2,048 at the scaled LR diverged.","a":"s5-overfitting-on-purpose","k":"fact"},{"t":"Regularisation mattered most with little data: +10.5 points on 5,000 images, +1.4 for weight decay on 50,000.","a":"s5-overfitting-on-purpose","k":"fact"},{"t":"Test loss can rise while test accuracy improves: the model grows more confident in its remaining errors.","a":"s5-overfitting-on-purpose","k":"fact"}]},{"n":5,"f":"05-data-augmentation.html","ti":"Data Augmentation","lv":"Beginner","e":[{"t":"Why augmentation works","a":"s1-why-augmentation-works","k":"section"},{"t":"Crop and flip, on the GPU","a":"s2-crop-and-flip-on-the-gpu","k":"section"},{"t":"Every augmentation, measured","a":"s3-every-augmentation-measured","k":"section"},{"t":"Mixup and CutMix: soft labels","a":"s4-mixup-and-cutmix-soft-labels","k":"section"},{"t":"Augmentations that break the label","a":"s5-augmentations-that-break-the-label","k":"section"},{"t":"Test-time augmentation and small data","a":"s6-test-time-augmentation-and-small-data","k":"section"},{"t":"Check your understanding","a":"s7-check-your-understanding","k":"section"},{"t":"Augmentation lab","a":"s3-every-augmentation-measured","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: augmentation policies for medical images","a":"s6-test-time-augmentation-and-small-data","k":"topic"},{"t":"Common mistakes","a":"s6-test-time-augmentation-and-small-data","k":"topic"},{"t":"Interview drill","a":"s6-test-time-augmentation-and-small-data","k":"topic"},{"t":"Augmentation teaches invariances: random crops and flips took the CNN from 87.6% to 91.1% on CIFAR-10.","a":"s6-test-time-augmentation-and-small-data","k":"fact"},{"t":"Useful augmentations lower training accuracy and raise test accuracy; the gap fell from 12.4 to 5.2 points with cutout.","a":"s6-test-time-augmentation-and-small-data","k":"fact"},{"t":"Mixup and CutMix need long training: at 30 epochs they cost 0.9 and 1.7 points.","a":"s6-test-time-augmentation-and-small-data","k":"fact"},{"t":"Flip TTA added about a point at twice the inference cost.","a":"s6-test-time-augmentation-and-small-data","k":"fact"},{"t":"Augmentation matters most with little data: +11.3 points on 5,000 images.","a":"s6-test-time-augmentation-and-small-data","k":"fact"}]},{"n":6,"f":"06-normalisation-layers.html","ti":"Batch Norm & Normalisation Layers","lv":"Beginner","e":[{"t":"What BatchNorm computes","a":"s1-what-batchnorm-computes","k":"section"},{"t":"With, without, and GroupNorm","a":"s2-with-without-and-groupnorm","k":"section"},{"t":"The train/eval switch, broken on purpose","a":"s3-the-train-eval-switch-broken-on-purpose","k":"section"},{"t":"Small batches when training","a":"s4-small-batches-when-training","k":"section"},{"t":"Shifted data: re-estimating the statistics","a":"s5-shifted-data-re-estimating-the-statistic","k":"section"},{"t":"Folding BatchNorm for deployment","a":"s6-folding-batchnorm-for-deployment","k":"section"},{"t":"Check your understanding","a":"s7-check-your-understanding","k":"section"},{"t":"BatchNorm lab","a":"s3-the-train-eval-switch-broken-on-purpose","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: synchronised BatchNorm in detection training","a":"s6-folding-batchnorm-for-deployment","k":"topic"},{"t":"Common mistakes","a":"s6-folding-batchnorm-for-deployment","k":"topic"},{"t":"Interview drill","a":"s6-folding-batchnorm-for-deployment","k":"topic"},{"t":"BatchNorm normalises each channel with batch statistics in training and with running averages in evaluation.","a":"s6-folding-batchnorm-for-deployment","k":"fact"},{"t":"It was the best layer here: 89.4% vs 84.8% for GroupNorm and 83.8% with none.","a":"s6-folding-batchnorm-for-deployment","k":"fact"},{"t":"Train mode at inference depends on the batch: 88.4% at 1,000, 71.3% at 4, 10.0% at batch 1, 15.2% for one-class batches.","a":"s6-folding-batchnorm-for-deployment","k":"fact"},{"t":"Train mode also overwrites the running statistics: one bad pass cost 11.3 points for good. Deep-copy before experiments.","a":"s6-folding-batchnorm-for-deployment","k":"fact"},{"t":"Re-estimating statistics on unlabelled shifted data recovered darkened-image accuracy from 85.3% to 88.2%.","a":"s6-folding-batchnorm-for-deployment","k":"fact"},{"t":"In eval mode BN is an affine map and folds into the preceding convolution: same accuracy, 7% faster.","a":"s6-folding-batchnorm-for-deployment","k":"fact"}]},{"n":7,"f":"07-residual-networks.html","ti":"Residual Networks","lv":"Beginner","e":[{"t":"The degradation problem","a":"s1-the-degradation-problem","k":"section"},{"t":"The residual block","a":"s2-the-residual-block","k":"section"},{"t":"Why it works: gradients","a":"s3-why-it-works-gradients","k":"section"},{"t":"Bottlenecks and the ResNet family","a":"s4-bottlenecks-and-the-resnet-family","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"Plain vs residual","a":"s3-why-it-works-gradients","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: the residual connection everywhere","a":"s4-bottlenecks-and-the-resnet-family","k":"topic"},{"t":"Common mistakes","a":"s4-bottlenecks-and-the-resnet-family","k":"topic"},{"t":"Interview drill","a":"s4-bottlenecks-and-the-resnet-family","k":"topic"},{"t":"Deeper plain networks can train worse, on the training set itself: that is degradation, not overfitting.","a":"s4-bottlenecks-and-the-resnet-family","k":"fact"},{"t":"A residual block outputs x + F(x); with matching shapes the shortcut is free.","a":"s4-bottlenecks-and-the-resnet-family","k":"fact"},{"t":"Plain 20 → 56 → 110 layers scored 88.2% → 79.6% → 12.7%; residual 89.8% → 90.8% → 91.4%, same layers and training.","a":"s4-bottlenecks-and-the-resnet-family","k":"fact"},{"t":"Bottlenecks (1×1 → 3×3 → 1×1) make deep, wide networks affordable: 17× cheaper than two 3 × 3s at 256 channels.","a":"s4-bottlenecks-and-the-resnet-family","k":"fact"}]},{"n":8,"f":"08-transfer-learning.html","ti":"Transfer Learning & Fine-Tuning","lv":"Beginner","e":[{"t":"Pretrained features","a":"s1-pretrained-features","k":"section"},{"t":"Oxford-IIIT Pets: four ways to train","a":"s2-oxford-iiit-pets-four-ways-to-train","k":"section"},{"t":"How much data do you need?","a":"s3-how-much-data-do-you-need","k":"section"},{"t":"A distant domain: satellite images","a":"s4-a-distant-domain-satellite-images","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"Transfer lab","a":"s2-oxford-iiit-pets-four-ways-to-train","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: medical imaging with a few thousand scans","a":"s4-a-distant-domain-satellite-images","k":"topic"},{"t":"Common mistakes","a":"s4-a-distant-domain-satellite-images","k":"topic"},{"t":"Interview drill","a":"s4-a-distant-domain-satellite-images","k":"topic"},{"t":"A linear probe on stored features takes seconds; always run it first as the baseline.","a":"s4-a-distant-domain-satellite-images","k":"fact"},{"t":"Two photos per breed gave 71% with fine-tuning; transfer is what makes tens of labels enough.","a":"s4-a-distant-domain-satellite-images","k":"fact"},{"t":"Fine-tuning with a modest LR was robust here; discriminative LRs did not help on this task. Measure, don’t assume.","a":"s4-a-distant-domain-satellite-images","k":"fact"},{"t":"Far-off domains (satellite tiles) still benefit, but the frozen features leave more on the table.","a":"s4-a-distant-domain-satellite-images","k":"fact"}]},{"n":9,"f":"09-evaluating-classifiers.html","ti":"Evaluating Image Classifiers","lv":"Beginner","e":[{"t":"The model and the splits","a":"s1-the-model-and-the-splits","k":"section"},{"t":"Per-class accuracy","a":"s2-per-class-accuracy","k":"section"},{"t":"Calibration: does 90% mean 90%?","a":"s3-calibration-does-90-mean-90","k":"section"},{"t":"A fresh test set","a":"s4-a-fresh-test-set","k":"section"},{"t":"Corruptions","a":"s5-corruptions","k":"section"},{"t":"Test-set reuse and error analysis","a":"s6-test-set-reuse-and-error-analysis","k":"section"},{"t":"Check your understanding","a":"s7-check-your-understanding","k":"section"},{"t":"Evaluation lab","a":"s3-calibration-does-90-mean-90","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: ImageNetV2","a":"s6-test-set-reuse-and-error-analysis","k":"topic"},{"t":"Common mistakes","a":"s6-test-set-reuse-and-error-analysis","k":"topic"},{"t":"Interview drill","a":"s6-test-set-reuse-and-error-analysis","k":"topic"},{"t":"Per-class accuracy ranged from 84.5% (cat) to 97.8% (automobile) behind a 92.9% average.","a":"s6-test-set-reuse-and-error-analysis","k":"fact"},{"t":"Label smoothing made it underconfident (T = 0.76): calibrate after training either way.","a":"s6-test-set-reuse-and-error-analysis","k":"fact"},{"t":"A fresh test set drawn the same way (CIFAR-10.1) cost 7.7 points: expect shift, and measure on new data.","a":"s6-test-set-reuse-and-error-analysis","k":"fact"},{"t":"Noise of σ = 16 cut accuracy to 54%; robustness follows the augmentations seen in training.","a":"s6-test-set-reuse-and-error-analysis","k":"fact"},{"t":"Decide on validation data, score the test set once, and read the most confident errors.","a":"s6-test-set-reuse-and-error-analysis","k":"fact"}]},{"n":10,"f":"10-what-a-cnn-sees.html","ti":"What a CNN Sees: Feature Maps & Grad-CAM","lv":"Beginner","e":[{"t":"First-layer filters","a":"s1-first-layer-filters","k":"section"},{"t":"Feature maps by depth","a":"s2-feature-maps-by-depth","k":"section"},{"t":"Which pixels mattered: saliency and Grad-CAM","a":"s3-which-pixels-mattered-saliency-and-grad-","k":"section"},{"t":"Shortcut learning, planted and found","a":"s4-shortcut-learning-planted-and-found","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"Inside ResNet-50","a":"s3-which-pixels-mattered-saliency-and-grad-","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: the scanner tag in chest X-rays","a":"s4-shortcut-learning-planted-and-found","k":"topic"},{"t":"Common mistakes","a":"s4-shortcut-learning-planted-and-found","k":"topic"},{"t":"Interview drill","a":"s4-shortcut-learning-planted-and-found","k":"topic"},{"t":"First-layer filters learn edges and colour blobs much like hand-made kernels.","a":"s4-shortcut-learning-planted-and-found","k":"fact"},{"t":"Feature maps lose resolution and gain meaning with depth: edges at 56 × 56, objects at 7 × 7.","a":"s4-shortcut-learning-planted-and-found","k":"fact"},{"t":"Models learn the easiest cue: a corner square on training birds led to 0% of real birds found.","a":"s4-shortcut-learning-planted-and-found","k":"fact"},{"t":"Averages hide shortcuts (80.7% looked normal); heat maps suggest them; controlled tests confirm them.","a":"s4-shortcut-learning-planted-and-found","k":"fact"}]},{"n":11,"f":"11-cnn-architectures.html","ti":"CNN Architectures: VGG to ConvNeXt","lv":"Intermediate","e":[{"t":"A decade of ideas","a":"s1-a-decade-of-ideas","k":"section"},{"t":"Measured: four kinds of cost","a":"s2-measured-four-kinds-of-cost","k":"section"},{"t":"Reading the trade-offs","a":"s3-reading-the-trade-offs","k":"section"},{"t":"Check your understanding","a":"s4-check-your-understanding","k":"section"},{"t":"Architecture explorer","a":"s2-measured-four-kinds-of-cost","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: “ResNet strikes back”","a":"s3-reading-the-trade-offs","k":"topic"},{"t":"Common mistakes","a":"s3-reading-the-trade-offs","k":"topic"},{"t":"Interview drill","a":"s3-reading-the-trade-offs","k":"topic"},{"t":"Training recipes matter as much: ResNet-50 went from 76.1% to 80.9% by retraining alone.","a":"s3-reading-the-trade-offs","k":"fact"},{"t":"Choose from the Pareto front measured on your target, then fine-tune the shortlist on your own data.","a":"s3-reading-the-trade-offs","k":"fact"}]},{"n":12,"f":"12-efficient-convolutions.html","ti":"Efficient Convolutions","lv":"Intermediate","e":[{"t":"Grouped, depthwise and pointwise","a":"s1-grouped-depthwise-and-pointwise","k":"section"},{"t":"FLOPs against time, one layer at a time","a":"s2-flops-against-time-one-layer-at-a-time","k":"section"},{"t":"Whole networks: GPU vs CPU","a":"s3-whole-networks-gpu-vs-cpu","k":"section"},{"t":"Does factorising cost accuracy?","a":"s4-does-factorising-cost-accuracy","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"FLOPs vs time","a":"s2-flops-against-time-one-layer-at-a-time","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: designing for the phone, then measuring on it","a":"s4-does-factorising-cost-accuracy","k":"topic"},{"t":"Common mistakes","a":"s4-does-factorising-cost-accuracy","k":"topic"},{"t":"Interview drill","a":"s4-does-factorising-cost-accuracy","k":"topic"},{"t":"Grouped convs divide cost by g; depthwise (g = C) filters each channel alone; pointwise (1 × 1) mixes channels.","a":"s4-does-factorising-cost-accuracy","k":"fact"},{"t":"Depthwise-separable = depthwise + pointwise: 7.9× fewer FLOPs at 64 channels.","a":"s4-does-factorising-cost-accuracy","k":"fact"},{"t":"On the GPU those savings shrink: 64× fewer FLOPs ran 3× faster, because depthwise layers are memory-bound.","a":"s4-does-factorising-cost-accuracy","k":"fact"},{"t":"MobileNet v2 was slower than ResNet-18 on the GPU at batch 1 and 2.9× faster on one CPU core.","a":"s4-does-factorising-cost-accuracy","k":"fact"},{"t":"Inverted residuals expand channels 6× in the middle; their wide tensors cost time and memory.","a":"s4-does-factorising-cost-accuracy","k":"fact"},{"t":"Count FLOPs to shortlist; time on the target hardware at the real batch size to decide.","a":"s4-does-factorising-cost-accuracy","k":"fact"}]},{"n":13,"f":"13-detection-basics.html","ti":"Detection Basics: Boxes, IoU, Anchors & NMS","lv":"Intermediate","e":[{"t":"Boxes and IoU","a":"s1-boxes-and-iou","k":"section"},{"t":"Predicting a box: offsets from an anchor","a":"s2-predicting-a-box-offsets-from-an-anchor","k":"section"},{"t":"Anchors: do they cover the objects?","a":"s3-anchors-do-they-cover-the-objects","k":"section"},{"t":"Non-maximum suppression","a":"s4-non-maximum-suppression","k":"section"},{"t":"Choosing the threshold, measured","a":"s5-choosing-the-threshold-measured","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"NMS on a crowd","a":"s4-non-maximum-suppression","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: counting people at an entrance","a":"s5-choosing-the-threshold-measured","k":"topic"},{"t":"Common mistakes","a":"s5-choosing-the-threshold-measured","k":"topic"},{"t":"Interview drill","a":"s5-choosing-the-threshold-measured","k":"topic"},{"t":"Boxes come as xyxy, xywh or cxcywh; convert once at the boundary.","a":"s5-choosing-the-threshold-measured","k":"fact"},{"t":"IoU = intersection / union; a 1-pixel shift costs a 10-pixel box 32% of its IoU and a 100-pixel box 4%.","a":"s5-choosing-the-threshold-measured","k":"fact"},{"t":"Detectors predict small offsets from anchors; encode and decode are exact inverses.","a":"s5-choosing-the-threshold-measured","k":"fact"},{"t":"Faster R-CNN’s 15 anchors over 5 levels gave 86% of COCO objects an anchor at IoU ≥ 0.5, one square anchor only 15%.","a":"s5-choosing-the-threshold-measured","k":"fact"},{"t":"NMS removes duplicates: without it person AP fell from 60.6 to 18.4; thresholds 0.4–0.7 were within a point.","a":"s5-choosing-the-threshold-measured","k":"fact"},{"t":"Greedy NMS fails in crowds; Soft-NMS and set-prediction detectors address it.","a":"s5-choosing-the-threshold-measured","k":"fact"}]},{"n":14,"f":"14-two-stage-detectors.html","ti":"Two-Stage Detectors: Faster R-CNN","lv":"Intermediate","e":[{"t":"From R-CNN to Faster R-CNN","a":"s1-from-r-cnn-to-faster-r-cnn","k":"section"},{"t":"Tracing one image","a":"s2-tracing-one-image","k":"section"},{"t":"Feature pyramids: which level for which box","a":"s3-feature-pyramids-which-level-for-which-b","k":"section"},{"t":"RoI Pool vs RoI Align","a":"s4-roi-pool-vs-roi-align","k":"section"},{"t":"Where the time goes, and three variants","a":"s5-where-the-time-goes-and-three-variants","k":"section"},{"t":"Fine-tuning a detector","a":"s6-fine-tuning-a-detector","k":"section"},{"t":"Check your understanding","a":"s7-check-your-understanding","k":"section"},{"t":"Faster R-CNN, stage by stage","a":"s4-roi-pool-vs-roi-align","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: when two-stage detectors are still the choice","a":"s6-fine-tuning-a-detector","k":"topic"},{"t":"Common mistakes","a":"s6-fine-tuning-a-detector","k":"topic"},{"t":"Interview drill","a":"s6-fine-tuning-a-detector","k":"topic"},{"t":"Stage 1 (RPN) turns 217,413 anchors into 1,000 class-agnostic proposals; stage 2 classifies and refines each one.","a":"s6-fine-tuning-a-detector","k":"fact"},{"t":"RoI Align samples exact fractional positions: 0 px error against RoI Pool’s 21.6 px.","a":"s6-fine-tuning-a-detector","k":"fact"},{"t":"Of 32 ms per image, 14 went to the backbone and 18 to the two-stage machinery.","a":"s6-fine-tuning-a-detector","k":"fact"},{"t":"The v2 recipe added about 10 AP; a MobileNet backbone was 3× faster and lost most on small objects.","a":"s6-fine-tuning-a-detector","k":"fact"}]},{"n":15,"f":"15-one-stage-detectors.html","ti":"One-Stage Detectors: YOLO, RetinaNet & Anchor-Free","lv":"Intermediate","e":[{"t":"Dense prediction","a":"s1-dense-prediction","k":"section"},{"t":"The imbalance, measured","a":"s2-the-imbalance-measured","k":"section"},{"t":"Focal loss","a":"s3-focal-loss","k":"section"},{"t":"Anchor-free and YOLO-style heads","a":"s4-anchor-free-and-yolo-style-heads","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"Focal loss and one-stage detectors","a":"s3-focal-loss","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: real-time detection on a factory line","a":"s4-anchor-free-and-yolo-style-heads","k":"topic"},{"t":"Common mistakes","a":"s4-anchor-free-and-yolo-style-heads","k":"topic"},{"t":"Interview drill","a":"s4-anchor-free-and-yolo-style-heads","k":"topic"},{"t":"One-stage detectors predict classes and boxes densely at every position, with no proposal stage.","a":"s4-anchor-free-and-yolo-style-heads","k":"fact"},{"t":"The catch is imbalance: 1,067 background anchors per object; with cross-entropy, easy background made 85% of the loss.","a":"s4-anchor-free-and-yolo-style-heads","k":"fact"},{"t":"Focal loss down-weights easy examples by (1 − p_t)^γ; the foreground share rose from 5% to 74%.","a":"s4-anchor-free-and-yolo-style-heads","k":"fact"},{"t":"FCOS predicts distances to box edges from points, no anchors; YOLO trades accuracy for real-time speed by design.","a":"s4-anchor-free-and-yolo-style-heads","k":"fact"}]},{"n":16,"f":"16-evaluating-detectors.html","ti":"Evaluating Detectors: mAP from Scratch","lv":"Intermediate","e":[{"t":"Step 1: match detections to ground truth","a":"s1-step-1-match-detections-to-ground-truth","k":"section"},{"t":"Step 2: precision–recall and average precision","a":"s2-step-2-precision-recall-and-average-prec","k":"section"},{"t":"Matching pycocotools exactly","a":"s3-matching-pycocotools-exactly","k":"section"},{"t":"What mAP hides","a":"s4-what-map-hides","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"Inside one mAP","a":"s3-matching-pycocotools-exactly","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: VOC’s 11-point AP and COCO’s 101-point AP","a":"s4-what-map-hides","k":"topic"},{"t":"Common mistakes","a":"s4-what-map-hides","k":"topic"},{"t":"Interview drill","a":"s4-what-map-hides","k":"topic"},{"t":"AP = mean interpolated precision at 101 recall levels; COCO AP also averages IoU 0.50:0.05:0.95 and classes.","a":"s4-what-map-hides","k":"fact"},{"t":"A from-scratch implementation matched pycocotools exactly (51.28) once every rule was copied.","a":"s4-what-map-hides","k":"fact"},{"t":"The same model: 70.8 at IoU 0.5, 7.0 at 0.95; small 33.0 vs large 63.2; per-class from 100 to 0.","a":"s4-what-map-hides","k":"fact"},{"t":"Report AP50/AP75, AP by size, per-class AP and precision/recall at the deployed threshold alongside mAP.","a":"s4-what-map-hides","k":"fact"}]},{"n":17,"f":"17-semantic-segmentation.html","ti":"Semantic Segmentation: FCN & U-Net","lv":"Intermediate","e":[{"t":"Per-pixel classification","a":"s1-per-pixel-classification","k":"section"},{"t":"U-Net: an encoder, a decoder, and skips","a":"s2-u-net-an-encoder-a-decoder-and-skips","k":"section"},{"t":"Four segmenters, measured","a":"s3-four-segmenters-measured","k":"section"},{"t":"Keeping resolution: dilated convolutions","a":"s4-keeping-resolution-dilated-convolutions","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"Segmentation lab","a":"s3-four-segmenters-measured","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: U-Net in medical imaging","a":"s4-keeping-resolution-dilated-convolutions","k":"topic"},{"t":"Common mistakes","a":"s4-keeping-resolution-dilated-convolutions","k":"topic"},{"t":"Interview drill","a":"s4-keeping-resolution-dilated-convolutions","k":"topic"},{"t":"One ×16 upsample gave 68.7 mIoU; a gradual decoder 72.6; U-Net’s skips 76.2, gained mostly at boundaries.","a":"s4-keeping-resolution-dilated-convolutions","k":"fact"},{"t":"Transposed convolution and bilinear + conv upsampling were within half a point.","a":"s4-keeping-resolution-dilated-convolutions","k":"fact"},{"t":"Dilated convolutions keep resolution: DeepLabV3 led the pretrained models at 65.3 mIoU on COCO/VOC classes.","a":"s4-keeping-resolution-dilated-convolutions","k":"fact"},{"t":"Report mIoU, not pixel accuracy: “background everywhere” had 57.7% pixel accuracy and 19.2 mIoU.","a":"s4-keeping-resolution-dilated-convolutions","k":"fact"}]},{"n":18,"f":"18-instance-segmentation-and-keypoints.html","ti":"Instance Segmentation & Keypoints","lv":"Intermediate","e":[{"t":"Three kinds of segmentation","a":"s1-three-kinds-of-segmentation","k":"section"},{"t":"Mask R-CNN: a mask head on Faster R-CNN","a":"s2-mask-r-cnn-a-mask-head-on-faster-r-cnn","k":"section"},{"t":"Box AP vs mask AP, measured","a":"s3-box-ap-vs-mask-ap-measured","k":"section"},{"t":"Keypoints: a heatmap per joint","a":"s4-keypoints-a-heatmap-per-joint","k":"section"},{"t":"Panoptic quality","a":"s5-panoptic-quality","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Instances, keypoints and PQ","a":"s3-box-ap-vs-mask-ap-measured","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: robotic picking and sports analytics","a":"s5-panoptic-quality","k":"topic"},{"t":"Common mistakes","a":"s5-panoptic-quality","k":"topic"},{"t":"Interview drill","a":"s5-panoptic-quality","k":"topic"},{"t":"Semantic labels pixels, instance separates countable objects, panoptic does both with one label per pixel.","a":"s5-panoptic-quality","k":"fact"},{"t":"Mask R-CNN adds a 28 × 28 per-class sigmoid mask head on RoIAligned features to Faster R-CNN.","a":"s5-panoptic-quality","k":"fact"},{"t":"Measured: 51.9 box AP and 46.3 mask AP; the gap is largest at strict IoU and on small objects.","a":"s5-panoptic-quality","k":"fact"},{"t":"Filled-in boxes scored as masks got 15.1 AP: the mask head carries the segmentation.","a":"s5-panoptic-quality","k":"fact"},{"t":"Keypoints are 56 × 56 heatmaps per joint, matched with scale-normalised OKS; PQ = SQ × RQ.","a":"s5-panoptic-quality","k":"fact"}]},{"n":19,"f":"19-vision-transformers.html","ti":"Vision Transformers from Scratch","lv":"Intermediate","e":[{"t":"Patches as tokens","a":"s1-patches-as-tokens","k":"section"},{"t":"The class token and position embeddings","a":"s2-the-class-token-and-position-embeddings","k":"section"},{"t":"The encoder, in plain PyTorch","a":"s3-the-encoder-in-plain-pytorch","k":"section"},{"t":"Where the parameters live","a":"s4-where-the-parameters-live","k":"section"},{"t":"Cost grows with the square of the tokens","a":"s5-cost-grows-with-the-square-of-the-tokens","k":"section"},{"t":"Changing resolution: interpolate the positions","a":"s6-changing-resolution-interpolate-the-posi","k":"section"},{"t":"What the class token looks at","a":"s7-what-the-class-token-looks-at","k":"section"},{"t":"Check your understanding","a":"s8-check-your-understanding","k":"section"},{"t":"ViT lab","a":"s4-where-the-parameters-live","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: one backbone for images, text and documents","a":"s7-what-the-class-token-looks-at","k":"topic"},{"t":"Common mistakes","a":"s7-what-the-class-token-looks-at","k":"topic"},{"t":"Interview drill","a":"s7-what-the-class-token-looks-at","k":"topic"},{"t":"A 30-line ViT loaded with torchvision’s weights matched it to about 2 × 10⁻⁶.","a":"s7-what-the-class-token-looks-at","k":"fact"},{"t":"Two thirds of ViT-B’s 86.6 M parameters are MLPs; no parameter depends on resolution except the position table.","a":"s7-what-the-class-token-looks-at","k":"fact"},{"t":"Attention cost and naive memory grow with tokens squared; fused attention fixes the memory, not the compute.","a":"s7-what-the-class-token-looks-at","k":"fact"},{"t":"A new resolution needs interpolated position embeddings, and ideally a short fine-tune.","a":"s7-what-the-class-token-looks-at","k":"fact"}]},{"n":20,"f":"20-training-vits.html","ti":"Training ViTs: Data, DeiT & ViT vs CNN","lv":"Intermediate","e":[{"t":"Inductive bias: what a CNN assumes","a":"s1-inductive-bias-what-a-cnn-assumes","k":"section"},{"t":"ViT vs ResNet-18 by dataset size","a":"s2-vit-vs-resnet-18-by-dataset-size","k":"section"},{"t":"DeiT: closing the gap with the recipe","a":"s3-deit-closing-the-gap-with-the-recipe","k":"section"},{"t":"Patch size: tokens against detail","a":"s4-patch-size-tokens-against-detail","k":"section"},{"t":"What to do in practice","a":"s5-what-to-do-in-practice","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"ViT training lab","a":"s2-vit-vs-resnet-18-by-dataset-size","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: picking a backbone for a medical-imaging start-up","a":"s5-what-to-do-in-practice","k":"topic"},{"t":"Common mistakes","a":"s5-what-to-do-in-practice","k":"topic"},{"t":"Interview drill","a":"s5-what-to-do-in-practice","k":"topic"},{"t":"CNNs build in locality, weight sharing and a hierarchy; ViTs must learn them from data.","a":"s5-what-to-do-in-practice","k":"fact"},{"t":"With matched step budgets, ResNet-18 beat a small ViT by 23.4 points at 5k CIFAR images and by 12.0 at 50k.","a":"s5-what-to-do-in-practice","k":"fact"},{"t":"Patch 4 beat both 8 and 2 on 32-pixel images; patch 2 cost 5.7× the time and lost 2.4 points.","a":"s5-what-to-do-in-practice","k":"fact"},{"t":"In practice: pre-trained ViT and fine-tune, or a CNN when training from scratch on small data.","a":"s5-what-to-do-in-practice","k":"fact"}]},{"n":21,"f":"21-swin-and-detr.html","ti":"Swin & DETR","lv":"Intermediate","e":[{"t":"Swin: attention inside windows","a":"s1-swin-attention-inside-windows","k":"section"},{"t":"Measured: window vs global, Swin vs ViT","a":"s2-measured-window-vs-global-swin-vs-vit","k":"section"},{"t":"DETR: detection as set prediction","a":"s3-detr-detection-as-set-prediction","k":"section"},{"t":"Check your understanding","a":"s4-check-your-understanding","k":"section"},{"t":"Swin and DETR lab","a":"s2-measured-window-vs-global-swin-vs-vit","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: satellite and pathology images","a":"s3-detr-detection-as-set-prediction","k":"topic"},{"t":"Common mistakes","a":"s3-detr-detection-as-set-prediction","k":"topic"},{"t":"Interview drill","a":"s3-detr-detection-as-set-prediction","k":"topic"},{"t":"Swin attends within 7 × 7 windows, shifts them every other block, and merges patches into a ResNet-like pyramid.","a":"s3-detr-detection-as-set-prediction","k":"fact"},{"t":"Window attention scales linearly: at 12,544 tokens, 115× faster than global with 23× less memory.","a":"s3-detr-detection-as-set-prediction","k":"fact"},{"t":"From 224 to 896 px, ViT-B slowed 67×, Swin-T 4.9×, ResNet-50 5.8×; Swin-T was slower than ViT-B at 224.","a":"s3-detr-detection-as-set-prediction","k":"fact"},{"t":"DETR predicts a set with 100 object queries, trained with Hungarian matching, and needs no NMS.","a":"s3-detr-detection-as-set-prediction","k":"fact"},{"t":"Measured: DETR 45.4 AP, 44.4 with NMS added; weak on small objects and slow to train.","a":"s3-detr-detection-as-set-prediction","k":"fact"}]},{"n":22,"f":"22-contrastive-self-supervised.html","ti":"Self-Supervised Learning: SimCLR & MoCo","lv":"Intermediate","e":[{"t":"Why learn without labels","a":"s1-why-learn-without-labels","k":"section"},{"t":"Views: the augmentations define the task","a":"s2-views-the-augmentations-define-the-task","k":"section"},{"t":"The InfoNCE loss","a":"s3-the-infonce-loss","k":"section"},{"t":"MoCo: negatives from a queue","a":"s4-moco-negatives-from-a-queue","k":"section"},{"t":"Measured: SimCLR on CIFAR-10","a":"s5-measured-simclr-on-cifar-10","k":"section"},{"t":"Label efficiency","a":"s6-label-efficiency","k":"section"},{"t":"What matters: the ablations","a":"s7-what-matters-the-ablations","k":"section"},{"t":"Check your understanding","a":"s8-check-your-understanding","k":"section"},{"t":"Contrastive learning lab","a":"s5-measured-simclr-on-cifar-10","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: defect inspection with few labelled faults","a":"s7-what-matters-the-ablations","k":"topic"},{"t":"Common mistakes","a":"s7-what-matters-the-ablations","k":"topic"},{"t":"Interview drill","a":"s7-what-matters-the-ablations","k":"topic"},{"t":"InfoNCE is a cross-entropy over cosine similarities divided by a temperature; the augmentations define what is ignored.","a":"s7-what-matters-the-ablations","k":"fact"}]},{"n":23,"f":"23-mae-and-dino.html","ti":"Masked Autoencoders & DINO","lv":"Intermediate","e":[{"t":"Masked image modelling","a":"s1-masked-image-modelling","k":"section"},{"t":"DINO: self-distillation with no labels and no negatives","a":"s2-dino-self-distillation-with-no-labels-an","k":"section"},{"t":"Frozen features, three ways of pre-training","a":"s3-frozen-features-three-ways-of-pre-traini","k":"section"},{"t":"DINO’s attention segments objects","a":"s4-dino-s-attention-segments-objects","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"MAE and DINO lab","a":"s2-dino-self-distillation-with-no-labels-an","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: one frozen backbone for many products","a":"s4-dino-s-attention-segments-objects","k":"topic"},{"t":"Common mistakes","a":"s4-dino-s-attention-segments-objects","k":"topic"},{"t":"Interview drill","a":"s4-dino-s-attention-segments-objects","k":"topic"},{"t":"MAE’s loss on hidden patches rose from 0.11 at 25% masking to 0.44 at 90%; reconstructions are blurry by design.","a":"s4-dino-s-attention-segments-objects","k":"fact"},{"t":"DINO matches a momentum teacher across crops with no negatives; centring plus sharpening prevent collapse.","a":"s4-dino-s-attention-segments-objects","k":"fact"}]},{"n":24,"f":"24-clip-and-zero-shot.html","ti":"CLIP & Zero-Shot Vision","lv":"Intermediate","e":[{"t":"Contrastive image–text training","a":"s1-contrastive-image-text-training","k":"section"},{"t":"Zero-shot classification","a":"s2-zero-shot-classification","k":"section"},{"t":"Zero-shot against linear probes","a":"s3-zero-shot-against-linear-probes","k":"section"},{"t":"Blind spots: text, counting and bias","a":"s4-blind-spots-text-counting-and-bias","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"CLIP lab","a":"s2-zero-shot-classification","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: searching a photo library by description","a":"s4-blind-spots-text-counting-and-bias","k":"topic"},{"t":"Common mistakes","a":"s4-blind-spots-text-counting-and-bias","k":"topic"},{"t":"Interview drill","a":"s4-blind-spots-text-counting-and-bias","k":"topic"},{"t":"CLIP trains an image and a text encoder so matching pairs are close, using InfoNCE over a batch of captions.","a":"s4-blind-spots-text-counting-and-bias","k":"fact"},{"t":"Zero-shot classification: embed “a photo of a {class}.” for each class and pick the nearest.","a":"s4-blind-spots-text-counting-and-bias","k":"fact"},{"t":"Measured zero-shot: 99%+ on Imagenette, 93.6% on 37 pet breeds (ViT-L/14), but only 63% on satellite land use.","a":"s4-blind-spots-text-counting-and-bias","k":"fact"},{"t":"Prompt wording moved accuracy by up to 18 points; domain-specific templates helped most where images were unusual.","a":"s4-blind-spots-text-counting-and-bias","k":"fact"},{"t":"A written label flipped ViT-B/32’s answer on 21.6% of photos; a supervised ResNet-50 was never fooled.","a":"s4-blind-spots-text-counting-and-bias","k":"fact"}]},{"n":25,"f":"25-sam-and-open-vocabulary.html","ti":"Foundation Models: SAM & Open-Vocabulary Detection","lv":"Advanced","e":[{"t":"Promptable segmentation","a":"s1-promptable-segmentation","k":"section"},{"t":"A heavy encoder and a light decoder","a":"s2-a-heavy-encoder-and-a-light-decoder","k":"section"},{"t":"Measured: SAM on COCO objects","a":"s3-measured-sam-on-coco-objects","k":"section"},{"t":"Open-vocabulary detection","a":"s4-open-vocabulary-detection","k":"section"},{"t":"Where they fail","a":"s5-where-they-fail","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Foundation-model lab","a":"s3-measured-sam-on-coco-objects","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: auto-labelling a new dataset","a":"s5-where-they-fail","k":"topic"},{"t":"Common mistakes","a":"s5-where-they-fail","k":"topic"},{"t":"Interview drill","a":"s5-where-they-fail","k":"topic"},{"t":"SAM segments whatever a point, box or mask prompt indicates, with no classes; one click returns three candidate masks.","a":"s5-where-they-fail","k":"fact"},{"t":"Its heavy ViT encoder runs once per image and the light decoder per prompt, so clicks are cheap.","a":"s5-where-they-fail","k":"fact"},{"t":"Open-vocabulary detectors score boxes against text embeddings, so the class list is an input.","a":"s5-where-they-fail","k":"fact"}]},{"n":26,"f":"26-autoencoders-and-vaes.html","ti":"Autoencoders & VAEs","lv":"Advanced","e":[{"t":"Autoencoders","a":"s1-autoencoders","k":"section"},{"t":"Why you cannot sample a plain autoencoder","a":"s2-why-you-cannot-sample-a-plain-autoencode","k":"section"},{"t":"Variational autoencoders","a":"s3-variational-autoencoders","k":"section"},{"t":"Measured: the KL weight","a":"s4-measured-the-kl-weight","k":"section"},{"t":"Why VAE samples are blurry","a":"s5-why-vae-samples-are-blurry","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Autoencoder lab","a":"s3-variational-autoencoders","k":"demo"},{"t":"The reparameterisation trick","a":"s3-variational-autoencoders","k":"topic"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: anomaly detection and the compressor inside Stable Diffusion","a":"s5-why-vae-samples-are-blurry","k":"topic"},{"t":"Common mistakes","a":"s5-why-vae-samples-are-blurry","k":"topic"},{"t":"Interview drill","a":"s5-why-vae-samples-are-blurry","k":"topic"},{"t":"An autoencoder compresses to a code and reconstructs; reconstruction PSNR rises with code size.","a":"s5-why-vae-samples-are-blurry","k":"fact"},{"t":"Measured: 16.6 dB with an 8-number code, 26.7 dB with 512; random codes from a large plain autoencoder decode to noise.","a":"s5-why-vae-samples-are-blurry","k":"fact"},{"t":"A VAE encodes a distribution, samples with z = μ + σε, and adds β × KL to N(0, 1) to the loss.","a":"s5-why-vae-samples-are-blurry","k":"fact"},{"t":"β prices information: β 0.1 used all 128 dimensions (117 nats), β 4 only 11 (7 nats), with PSNR 22.7 → 16.4 dB.","a":"s5-why-vae-samples-are-blurry","k":"fact"},{"t":"MSE decoders produce averages, which is why VAE samples are blurry; GANs and diffusion fix the generation step.","a":"s5-why-vae-samples-are-blurry","k":"fact"}]},{"n":27,"f":"27-gans.html","ti":"Generative Adversarial Networks","lv":"Advanced","e":[{"t":"The adversarial game","a":"s1-the-adversarial-game","k":"section"},{"t":"Mode collapse, seen in two dimensions","a":"s2-mode-collapse-seen-in-two-dimensions","k":"section"},{"t":"DCGAN on CIFAR-10","a":"s3-dcgan-on-cifar-10","k":"section"},{"t":"Conditional GANs","a":"s4-conditional-gans","k":"section"},{"t":"Check your understanding","a":"s5-check-your-understanding","k":"section"},{"t":"GAN lab","a":"s2-mode-collapse-seen-in-two-dimensions","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: where GANs are still used","a":"s4-conditional-gans","k":"topic"},{"t":"Common mistakes","a":"s4-conditional-gans","k":"topic"},{"t":"Interview drill","a":"s4-conditional-gans","k":"topic"},{"t":"Use the non-saturating generator loss; the minimax one has vanishing gradients early.","a":"s4-conditional-gans","k":"fact"},{"t":"Conditional GANs give both networks the label; a projection discriminator checks image and label agree.","a":"s4-conditional-gans","k":"fact"}]},{"n":28,"f":"28-diffusion-from-scratch.html","ti":"Diffusion Models from Scratch","lv":"Advanced","e":[{"t":"The forward process: destroying an image slowly","a":"s1-the-forward-process-destroying-an-image-","k":"section"},{"t":"The loss: predict the noise","a":"s2-the-loss-predict-the-noise","k":"section"},{"t":"The denoiser: a U-Net that knows the time","a":"s3-the-denoiser-a-u-net-that-knows-the-time","k":"section"},{"t":"Sampling: walking back from noise","a":"s4-sampling-walking-back-from-noise","k":"section"},{"t":"Measured","a":"s5-measured","k":"section"},{"t":"Noise schedules","a":"s6-noise-schedules","k":"section"},{"t":"Check your understanding","a":"s7-check-your-understanding","k":"section"},{"t":"Diffusion lab","a":"s4-sampling-walking-back-from-noise","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: generation costs are step counts","a":"s6-noise-schedules","k":"topic"},{"t":"Common mistakes","a":"s6-noise-schedules","k":"topic"},{"t":"Interview drill","a":"s6-noise-schedules","k":"topic"},{"t":"The forward process mixes an image with noise in closed form: x t = √ᾱ t x 0 + √(1 − ᾱ t ) ε.","a":"s6-noise-schedules","k":"fact"},{"t":"Training is MSE between the added noise and a time-conditioned U-Net’s prediction of it.","a":"s6-noise-schedules","k":"fact"},{"t":"Trained here: 7.3 M parameters, 40,000 steps, 45 minutes, recognisable CIFAR-10 objects from noise.","a":"s6-noise-schedules","k":"fact"},{"t":"Sampling cost is network calls: 204 ms per image with 1,000 DDPM steps, 2 ms with 10 DDIM steps.","a":"s6-noise-schedules","k":"fact"},{"t":"The cosine schedule removes information more evenly than the linear one.","a":"s6-noise-schedules","k":"fact"}]},{"n":29,"f":"29-latent-diffusion-and-guidance.html","ti":"Latent Diffusion, Samplers & Guidance","lv":"Advanced","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":30,"f":"30-evaluating-generative-models.html","ti":"Evaluating Generative Models","lv":"Advanced","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":31,"f":"31-video-understanding.html","ti":"Video Understanding","lv":"Advanced","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":32,"f":"32-optical-flow-and-tracking.html","ti":"Optical Flow & Object Tracking","lv":"Advanced","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":33,"f":"33-camera-geometry-and-depth.html","ti":"Camera Geometry, Stereo & Depth","lv":"Advanced","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":34,"f":"34-nerf-and-gaussian-splatting.html","ti":"NeRF & Gaussian Splatting","lv":"Advanced","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":35,"f":"35-ocr-and-documents.html","ti":"OCR & Document Understanding","lv":"Advanced","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":36,"f":"36-image-retrieval-and-metric-learning.html","ti":"Image Retrieval & Metric Learning","lv":"Advanced","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":37,"f":"37-robustness-and-adversarial-examples.html","ti":"Robustness & Adversarial Examples","lv":"Expert","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":38,"f":"38-deploying-vision-models.html","ti":"Deploying Vision Models","lv":"Expert","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":39,"f":"39-debugging-vision-pipelines.html","ti":"Debugging Vision Pipelines & Datasets","lv":"Expert","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":40,"f":"40-interview-playbook.html","ti":"The CV Interview Playbook","lv":"Expert","e":[{"t":"The four question types","a":"s1-the-four-question-types","k":"section"},{"t":"Formulas to know by heart","a":"s2-formulas-to-know-by-heart","k":"section"},{"t":"Concept questions, with the numbers","a":"s3-concept-questions-with-the-numbers","k":"section"},{"t":"Debugging scenarios","a":"s4-debugging-scenarios","k":"section"},{"t":"Design rounds","a":"s5-design-rounds","k":"section"},{"t":"Check your understanding","a":"s6-check-your-understanding","k":"section"},{"t":"Interview calculators","a":"s2-formulas-to-know-by-heart","k":"demo"},{"t":"What you need before this chapter","a":"","k":"topic"},{"t":"Use case: a worked design answer in outline","a":"s5-design-rounds","k":"topic"},{"t":"Common mistakes","a":"s5-design-rounds","k":"topic"},{"t":"Interview drill","a":"s5-design-rounds","k":"topic"},{"t":"Four question types: concept, arithmetic, debugging, design. Each has a known shape.","a":"s5-design-rounds","k":"fact"},{"t":"Concept answers: mechanism, a measured number, a limit.","a":"s5-design-rounds","k":"fact"},{"t":"Debug in order: reproduce, inputs, mode and numerics, data, then the model.","a":"s5-design-rounds","k":"fact"},{"t":"Design from requirements and metric first, and put numbers on every step through to serving.","a":"s5-design-rounds","k":"fact"}]},{"n":41,"f":"41-case-alexnet-and-imagenet.html","ti":"Case Study: AlexNet and ImageNet","lv":"Case Studies","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":42,"f":"42-case-resnet.html","ti":"Case Study: ResNet","lv":"Case Studies","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":43,"f":"43-case-yolo.html","ti":"Case Study: YOLO’s Lineage","lv":"Case Studies","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":44,"f":"44-case-self-driving-perception.html","ti":"Case Study: Self-Driving Perception","lv":"Case Studies","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":45,"f":"45-case-face-id.html","ti":"Case Study: Face ID","lv":"Case Studies","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":46,"f":"46-case-stable-diffusion.html","ti":"Case Study: Stable Diffusion","lv":"Case Studies","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":47,"f":"47-case-segment-anything.html","ti":"Case Study: Segment Anything","lv":"Case Studies","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]},{"n":48,"f":"48-case-visual-search.html","ti":"Case Study: Visual Search","lv":"Case Studies","e":[{"t":"What this chapter will cover","a":"s1-what-this-chapter-will-cover","k":"section"}]}];
window.CV_CARDS = [{"n":0.1,"ti":"Images as Tensors","f":"p1-images-as-tensors.html","lv":"Prerequisites","q":"An image array has shape (300, 451, 3). Which call turns it into the layout a PyTorch convolution expects?","o":["t.reshape(3, 300, 451)","t.permute(2, 0, 1)","t.view(3, 300, 451)","t.permute(2, 1, 0)"],"a":1,"w":"permute moves the channel axis to the front. reshape and view keep memory order and scramble the channels; permute(2, 1, 0) also swaps height and width."},{"n":0.1,"ti":"Images as Tensors","f":"p1-images-as-tensors.html","lv":"Prerequisites","q":"What is torch.tensor([200], dtype=torch.uint8) + 100 ?","o":["300","255","44","An overflow error"],"a":2,"w":"uint8 arithmetic wraps modulo 256: 300 − 256 = 44. It does not saturate at 255 and it does not raise."},{"n":0.1,"ti":"Images as Tensors","f":"p1-images-as-tensors.html","lv":"Prerequisites","q":"Which library returns pixels in BGR order by default?","o":["OpenCV","PIL","scikit-image","torchvision’s decode_image"],"a":0,"w":"cv2.imread gives BGR. The pixel (150, 225) of the cat came back as [124, 150, 190] from OpenCV and [190, 150, 124] from the others."},{"n":0.1,"ti":"Images as Tensors","f":"p1-images-as-tensors.html","lv":"Prerequisites","q":"On the Imagenette validation set, which mistake left ResNet-50’s accuracy almost unchanged?","o":["Feeding 0–255 values","Using reshape instead of permute","Normalising twice","Skipping normalisation (values 0 to 1)"],"a":3,"w":"Skipping normalisation cost about one point (87.18% to 86.22%). The other three scored 0.00%, 0.00% and 0.13%."},{"n":0.1,"ti":"Images as Tensors","f":"p1-images-as-tensors.html","lv":"Prerequisites","q":"After the standard ImageNet preprocessing, what range of values should a batch roughly have?","o":["0 to 255","About −2.1 to 2.6","0 to 1","−1 to 1 exactly"],"a":1,"w":"Black in the red channel is (0 − 0.485) / 0.229 = −2.118 and white in the blue channel is (1 − 0.406) / 0.225 = 2.64."},{"n":0.2,"ti":"PyTorch & the Training Loop","f":"p2-pytorch-training-loop.html","lv":"Prerequisites","q":"What should the very first training loss of a fresh 10-class classifier be, roughly?","o":["0","About 2.3","About 10","It can be anything"],"a":1,"w":"Near-uniform predictions give cross-entropy ln 10 = 2.303. The measured first loss was 2.41."},{"n":0.2,"ti":"PyTorch & the Training Loop","f":"p2-pytorch-training-loop.html","lv":"Prerequisites","q":"Why does forgetting opt.zero_grad() make training blow up?","o":["The optimiser stops updating","The loss is computed twice","The gradients become zero","backward() adds into .grad , so each step uses the sum of all previous gradients"],"a":3,"w":"Accumulation is by design. Without clearing, steps keep growing: the loss hit 120,332 by step 50 and then NaN."},{"n":0.2,"ti":"PyTorch & the Training Loop","f":"p2-pytorch-training-loop.html","lv":"Prerequisites","q":"What does F.cross_entropy expect as its first argument?","o":["Raw logits","Softmax probabilities","Log-probabilities from log_softmax","One-hot labels"],"a":0,"w":"It applies log-softmax itself. Passing probabilities softmaxes twice; that run reached 49.7% instead of 52.6%."},{"n":0.2,"ti":"PyTorch & the Training Loop","f":"p2-pytorch-training-loop.html","lv":"Prerequisites","q":"An MLP trained with SGD at lr 0.2 ends with NaN loss. What will its test accuracy on balanced 10-class data be?","o":["About 50%","0%","About 10%","Impossible to say"],"a":2,"w":"NaN weights give the same prediction for every image, so it is right for exactly one class in ten: 10.00%."},{"n":0.2,"ti":"PyTorch & the Training Loop","f":"p2-pytorch-training-loop.html","lv":"Prerequisites","q":"Why overfit one small batch before a long run?","o":["It initialises the weights better","A working model and loop must reach near-zero loss on it; if not, there is a bug, found in seconds","It measures test accuracy","It sets the learning rate automatically"],"a":1,"w":"The MLP reached 100% on 64 images by step 10. A model that cannot memorise 64 images has a bug in the model, the loss or the loop."},{"n":0.3,"ti":"Colour Spaces, Gamma & Image Formats","f":"p3-colour-gamma-and-formats.html","lv":"Prerequisites","q":"In sRGB, which stored value emits half the light of 255?","o":["128","64","About 188","About 220"],"a":2,"w":"sRGB is gamma-encoded. Linear 0.5 converts to 187.5; a stored 128 is only about 0.216 of full light."},{"n":0.3,"ti":"Colour Spaces, Gamma & Image Formats","f":"p3-colour-gamma-and-formats.html","lv":"Prerequisites","q":"Which loader applies a JPEG’s EXIF orientation tag by default?","o":["cv2.imread","PIL.Image.open","torchvision.io.decode_jpeg","torchvision.io.decode_image"],"a":0,"w":"OpenCV rotated the 426 × 320 test file to 320 × 426. PIL needs ImageOps.exif_transpose , and torchvision needs apply_exif_orientation=True ."},{"n":0.3,"ti":"Colour Spaces, Gamma & Image Formats","f":"p3-colour-gamma-and-formats.html","lv":"Prerequisites","q":"Re-encoding Imagenette’s own JPEGs at quality 75 gave a higher PSNR than at quality 95. Why?","o":["q75 files are larger","PSNR is measured wrongly","q95 adds noise on purpose","The originals were saved at q75, so the same quantisation table re-produces nearly the same values"],"a":3,"w":"The originals averaged 25.4 KB, exactly the q75 size. Re-quantising with the same table changes almost nothing; q95’s different table moves every coefficient a little."},{"n":0.3,"ti":"Colour Spaces, Gamma & Image Formats","f":"p3-colour-gamma-and-formats.html","lv":"Prerequisites","q":"What is the greyscale value of RGB (200, 120, 40) with the standard luma weights?","o":["120","About 135","200","About 92"],"a":1,"w":"0.299 × 200 + 0.587 × 120 + 0.114 × 40 = 134.78. The plain mean is 120."},{"n":0.3,"ti":"Colour Spaces, Gamma & Image Formats","f":"p3-colour-gamma-and-formats.html","lv":"Prerequisites","q":"Which change cost ResNet-50 the least accuracy on Imagenette?","o":["Rotating 90°","JPEG quality 8","Mirroring left to right","Swapping to BGR"],"a":2,"w":"Mirroring cost nothing (87.32% both ways): the model was trained with horizontal flips. Rotating cost 11 points, q8 12 points, BGR 4.9."},{"n":0.4,"ti":"Geometry: Coordinates & Transforms","f":"p4-geometry-and-transforms.html","lv":"Prerequisites","q":"Why is a point written as (x, y, 1) for geometric transforms?","o":["To store colour","So translation, like rotation and scale, becomes a matrix product","To make the maths use integers","To mark the pixel as valid"],"a":1,"w":"With homogeneous coordinates every affine transform, translation included, is a 3 × 3 matrix, so sequences of transforms compose into one matrix."},{"n":0.4,"ti":"Geometry: Coordinates & Transforms","f":"p4-geometry-and-transforms.html","lv":"Prerequisites","q":"You want to rotate an image about its centre (cx, cy). Which matrix, applied to (x, y, 1), does it?","o":["R · T(cx, cy)","T(cx, cy) · T(−cx, −cy) · R","T(−cx, −cy) · R · T(cx, cy)","T(cx, cy) · R · T(−cx, −cy)"],"a":3,"w":"Read right to left: move the centre to the origin, rotate, move back. It matched cv2.getRotationMatrix2D to 7 × 10⁻¹⁵."},{"n":0.4,"ti":"Geometry: Coordinates & Transforms","f":"p4-geometry-and-transforms.html","lv":"Prerequisites","q":"Which interpolation should you use to resize a segmentation label mask?","o":["Nearest","Bilinear","Bicubic","Antialiased bilinear"],"a":0,"w":"Labels are categories. Blending class 1 and class 3 gives class 2, which is wrong. Nearest only ever copies existing labels."},{"n":0.4,"ti":"Geometry: Coordinates & Transforms","f":"p4-geometry-and-transforms.html","lv":"Prerequisites","q":"How many point correspondences determine a homography?","o":["2","3","4","9"],"a":2,"w":"H has 9 entries but is defined up to scale, so 8 unknowns; each point pair gives two equations. Four pairs (no three on a line) fix it. An affine transform needs only three."},{"n":0.4,"ti":"Geometry: Coordinates & Transforms","f":"p4-geometry-and-transforms.html","lv":"Prerequisites","q":"An image 451 pixels wide is flipped left to right. What does the box (100, 50, 220, 180) become?","o":["(351, 50, 231, 180)","(231, 50, 351, 180)","(100, 50, 220, 180)","(451, 50, 571, 180)"],"a":1,"w":"x maps to W − x, and the corners swap roles so that x1 < x2: (451 − 220, 50, 451 − 100, 180)."},{"n":0.5,"ti":"Classical Filtering: Blur, Edges & Kernels","f":"p5-classical-filtering.html","lv":"Prerequisites","q":"A kernel’s weights sum to 0. What is its output on a perfectly flat region of the image?","o":["The original brightness","255","0","Half the brightness"],"a":2,"w":"Every pixel is the same value v, so the output is v × (sum of weights) = 0. Such kernels (Sobel, Laplacian) respond only to change."},{"n":0.5,"ti":"Classical Filtering: Blur, Edges & Kernels","f":"p5-classical-filtering.html","lv":"Prerequisites","q":"Which of these computes a true convolution, flipping the kernel?","o":["cv2.filter2D","scipy.ndimage.convolve","torch.nn.functional.conv2d","All of them"],"a":1,"w":"SciPy’s convolve flips the kernel; it gave exactly the negative of the hand-written Sobel result. OpenCV and PyTorch compute correlation."},{"n":0.5,"ti":"Classical Filtering: Blur, Edges & Kernels","f":"p5-classical-filtering.html","lv":"Prerequisites","q":"How many multiplies per pixel does a separable 31 × 31 Gaussian need?","o":["961","31","480","62"],"a":3,"w":"Two 1-D passes of 31 weights each: 62, against 961 for the full 2-D kernel."},{"n":0.5,"ti":"Classical Filtering: Blur, Edges & Kernels","f":"p5-classical-filtering.html","lv":"Prerequisites","q":"An image has 5% of its pixels randomly set to pure black or white. Which filter removed this best?","o":["A 3 × 3 median","A 5 × 5 box blur","A Gaussian blur, σ = 2","A bilateral filter"],"a":0,"w":"Median 3 × 3 reached 33.92 dB; the best averaging filter 28.66 and bilateral 21.37. A median ignores outliers; an average spreads them."},{"n":0.5,"ti":"Classical Filtering: Blur, Edges & Kernels","f":"p5-classical-filtering.html","lv":"Prerequisites","q":"Why did a 9 × 9 box blur with zero padding make the left edge of the photo dark?","o":["The kernel was not normalised","uint8 overflow","Part of the kernel averaged in zeros from outside the image","The Sobel step removed brightness"],"a":2,"w":"At the leftmost column, 4 of the kernel’s 9 columns lie outside the image, where zero padding supplies black: 68.7 instead of about 124."},{"n":0.6,"ti":"Loading Image Data Fast","f":"p6-loading-image-data.html","lv":"Prerequisites","q":"Why must DataLoader code with workers sit under if __name__ == \"__main__\": on Windows?","o":["It makes the loader faster","It enables pinned memory","Workers are spawned as new processes that import the script, which would otherwise start loaders recursively","PyTorch requires it for CUDA"],"a":2,"w":"On Windows and macOS workers start by spawning, which re-imports the main module. The guard stops that import from re-running the training code."},{"n":0.6,"ti":"Loading Image Data Fast","f":"p6-loading-image-data.html","lv":"Prerequisites","q":"Decoding the same photo at 1,280 px instead of 320 px took how much longer?","o":["About the same","About 15 times","About 2 times","About 100 times"],"a":1,"w":"6.257 ms against 0.423 ms: decode cost grows roughly with the number of pixels (16 times as many here)."},{"n":0.6,"ti":"Loading Image Data Fast","f":"p6-loading-image-data.html","lv":"Prerequisites","q":"A loader produces 1,074 images/s and the GPU can train ResNet-18 on 2,857 images/s. Roughly how busy is the GPU?","o":["100%","About 85%","About 60%","About 38%"],"a":3,"w":"The pipeline runs at the slower stage: 1,074 / 2,857 ≈ 0.38. The GPU waits the rest of the time."},{"n":0.6,"ti":"Loading Image Data Fast","f":"p6-loading-image-data.html","lv":"Prerequisites","q":"Which change raised 8-worker throughput from 3,939 to 6,357 images/s?","o":["Returning uint8 batches and normalising on the GPU","Pinning memory","Using batch size 256","Using PIL instead of torchvision"],"a":0,"w":"The workers skip the float conversion and normalisation, and each batch is a quarter of the bytes. Pinning made little difference here."},{"n":0.6,"ti":"Loading Image Data Fast","f":"p6-loading-image-data.html","lv":"Prerequisites","q":"How do you test whether training is limited by data loading?","o":["Double the learning rate","Check the loss curve","Compare the step rate on data already on the GPU with the real loop, and time waits on the loader","Count the model’s parameters"],"a":2,"w":"ResNet-18 ran 2,857 images/s on synthetic data and 2,813 with the real loader, waiting 3.9% of the time: compute-bound."},{"n":0.7,"ti":"Losses & Metrics for Classifiers","f":"p7-losses-and-metrics.html","lv":"Prerequisites","q":"What does exp(z) / exp(z).sum() return for logits [1000, 0, −5] in float32?","o":["[1, 0, 0]","[NaN, 0, 0]","[0.33, 0.33, 0.33]","An overflow exception"],"a":1,"w":"e^1000 overflows to infinity, and infinity / infinity is NaN. torch.softmax subtracts the max first and returns [1, 0, 0]."},{"n":0.7,"ti":"Losses & Metrics for Classifiers","f":"p7-losses-and-metrics.html","lv":"Prerequisites","q":"The model called 1,000 images “dog”, and 610 of them were dogs. Which metric is 0.61?","o":["Recall for dog","Accuracy","F1 for dog","Precision for dog"],"a":3,"w":"Precision is the share of predicted positives that are correct. Recall would be the share of real dogs that were found (0.83 here)."},{"n":0.7,"ti":"Losses & Metrics for Classifiers","f":"p7-losses-and-metrics.html","lv":"Prerequisites","q":"Cats are 10% of a test set. What accuracy does “always answer not-cat” get on the cat-vs-rest task?","o":["90%","10%","50%","0%"],"a":0,"w":"It is right on all 9,000 non-cats and wrong on 1,000 cats: 90%, with a recall of zero. That is the accuracy paradox."},{"n":0.7,"ti":"Losses & Metrics for Classifiers","f":"p7-losses-and-metrics.html","lv":"Prerequisites","q":"Lowering the threshold of a cat detector usually does what?","o":["Raises precision and recall","Lowers both","Raises recall and lowers precision","Changes neither"],"a":2,"w":"More images are called cats: more real cats are found, and more non-cats are wrongly included."},{"n":0.7,"ti":"Losses & Metrics for Classifiers","f":"p7-losses-and-metrics.html","lv":"Prerequisites","q":"Why is cross-entropy used for training instead of accuracy?","o":["It is faster to compute","Accuracy has zero gradient almost everywhere; cross-entropy is smooth and gives a signal on every image","Accuracy cannot be computed on a GPU","Cross-entropy ignores mistakes"],"a":1,"w":"Small weight changes rarely flip a prediction, so accuracy does not change and gives no gradient. Cross-entropy changes smoothly with every probability."},{"n":0.8,"ti":"GPU Memory & Throughput for Images","f":"p8-gpu-memory-and-throughput.html","lv":"Prerequisites","q":"What took most of the memory when training ResNet-50 at batch 256?","o":["The weights","The gradients","The optimiser’s momentum","Activations saved for the backward pass"],"a":3,"w":"Weights, gradients and momentum are about 100 MB each; activations were about 42 MB per image, roughly 10.9 GB of the 11.2 GB peak."},{"n":0.8,"ti":"GPU Memory & Throughput for Images","f":"p8-gpu-memory-and-throughput.html","lv":"Prerequisites","q":"Going from 224 × 224 to 448 × 448 at the same batch size multiplies activation memory by about…","o":["2","4","8","It stays the same"],"a":1,"w":"Activations scale with height × width: (448/224)² = 4. Measured at batch 32: 1,737 MB to 5,812 MB."},{"n":0.8,"ti":"GPU Memory & Throughput for Images","f":"p8-gpu-memory-and-throughput.html","lv":"Prerequisites","q":"Which configuration trained ResNet-50 fastest here?","o":["fp32","fp32 + channels-last","bf16 autocast + channels-last","bf16 autocast alone"],"a":2,"w":"1,200 images/s against 928 for bf16 alone, 576 for fp32 and 122 for fp32 with channels-last."},{"n":0.8,"ti":"GPU Memory & Throughput for Images","f":"p8-gpu-memory-and-throughput.html","lv":"Prerequisites","q":"Why did inference at batch 64 give 14.6× the throughput of batch 1?","o":["At batch 1 the GPU is mostly idle between small kernel launches; a large batch keeps it busy","Batch 64 uses less precision","Batch 1 runs on the CPU","Batching skips layers"],"a":0,"w":"Per-batch overheads are paid once per batch. At batch 1 they dominate: 3.74 ms for one image, 16.4 ms for 64."},{"n":0.8,"ti":"GPU Memory & Throughput for Images","f":"p8-gpu-memory-and-throughput.html","lv":"Prerequisites","q":"A run hits CUDA out of memory. Which fix keeps the same effective batch size?","o":["Lower the resolution","Use a smaller model","Delete the optimiser state","Halve the batch and accumulate gradients over two steps"],"a":3,"w":"Two half-batches with one optimiser step give the same update (for models without batch-statistics layers) at about half the activation memory."},{"n":1,"ti":"What Computer Vision Is","f":"01-what-computer-vision-is.html","lv":"Beginner","q":"Which task outputs a class label for every pixel?","o":["Classification","Detection","Semantic segmentation","Retrieval"],"a":2,"w":"A semantic segmenter outputs an (H, W) map of class indices. Detection outputs boxes; classification one label per image."},{"n":1,"ti":"What Computer Vision Is","f":"01-what-computer-vision-is.html","lv":"Beginner","q":"Why did the ImageNet classifier call the astronaut photo “crash helmet”?","o":["ImageNet’s 1,000 classes do not include “person” or “astronaut”","The image was preprocessed wrongly","The model is too small","The photo is black and white"],"a":0,"w":"A classifier must pick one of its own labels. The detector, trained on COCO, found the person with 0.994."},{"n":1,"ti":"What Computer Vision Is","f":"01-what-computer-vision-is.html","lv":"Beginner","q":"Which of the three models was slowest per image on this GPU?","o":["The classifier","The segmenter","All took the same time","The detector"],"a":3,"w":"Faster R-CNN took about 26–33 ms: it scores many candidate regions, refines each box and removes duplicates. The classifier took about 4 ms."},{"n":1,"ti":"What Computer Vision Is","f":"01-what-computer-vision-is.html","lv":"Beginner","q":"The classifier gave “bubble” 45.7% for the Hubble deep field. What does that show?","o":["The model knows galaxies look like bubbles","Softmax picks the least unlikely known class; a high score does not mean the input is in distribution","45.7% means the model is unsure","The image needed a higher resolution"],"a":1,"w":"Probabilities sum to 1 over known classes, so an unknown input still gets a winner, here with more confidence than a real French horn (39.8%)."},{"n":1,"ti":"What Computer Vision Is","f":"01-what-computer-vision-is.html","lv":"Beginner","q":"The segmenter labelled the garbage-truck photo entirely as background. Why?","o":["The truck was too small","Segmenters cannot see vehicles","Its 20 Pascal VOC classes include bus and car but not truck","The threshold was too high"],"a":2,"w":"With no truck class, “background” was its best option. The COCO-trained detector, which has a truck class, found it with 0.999."},{"n":2,"ti":"Convolutions in Depth","f":"02-convolutions-in-depth.html","lv":"Beginner","q":"How many parameters does nn.Conv2d(64, 128, kernel_size=3) have?","o":["1,152","73,856","8,192","589,824"],"a":1,"w":"128 kernels of 3 × 3 × 64 = 576 weights, plus 128 biases: 73,728 + 128."},{"n":2,"ti":"Convolutions in Depth","f":"02-convolutions-in-depth.html","lv":"Beginner","q":"What is the output width for input 224, kernel 3, stride 2, padding 0, dilation 1?","o":["112","110","111","113"],"a":2,"w":"(224 + 0 − 2 − 1) // 2 + 1 = 110 + 1 = 111. The division rounds down."},{"n":2,"ti":"Convolutions in Depth","f":"02-convolutions-in-depth.html","lv":"Beginner","q":"What does im2col trade for speed?","o":["Memory: every patch is copied into a column, about K² times the input size","Accuracy: it approximates the convolution","It needs the kernel to be separable","It only works with stride 1"],"a":0,"w":"It is exact (matched F.conv2d to 10⁻¹⁴) and turns the layer into one matrix multiply, but the columns were 441 MB for a 49 MB input."},{"n":2,"ti":"Convolutions in Depth","f":"02-convolutions-in-depth.html","lv":"Beginner","q":"Two conv layers had the same FLOPs. Why was the 3 → 64 layer at 224 × 224 ten times slower per FLOP than the 64 → 64 layer at 56 × 56?","o":["It used a bigger kernel","It ran on the CPU","cuDNN does not support 3 channels","With 3 input channels each output needs few multiply-adds, so moving the large output dominates: it is memory-bound"],"a":3,"w":"27 multiply-adds per output and a huge 224 × 224 × 64 output per image: arithmetic per byte is low, so memory bandwidth sets the speed (6.8 vs 70 TFLOPS)."},{"n":2,"ti":"Convolutions in Depth","f":"02-convolutions-in-depth.html","lv":"Beginner","q":"ResNet-50’s layer4 has a theoretical receptive field of 427 pixels. How wide was the square holding 90% of the gradient in the trained network?","o":["427 pixels","About 285 pixels","About 32 pixels","The whole image"],"a":1,"w":"The gradient fades from the centre, so the effective receptive field (285) is about two thirds of the theoretical one."},{"n":3,"ti":"Building a CNN","f":"03-building-a-cnn.html","lv":"Beginner","q":"A (N, 32, 32, 32) tensor goes through a 2 × 2 max pool. What comes out?","o":["(N, 16, 32, 32)","(N, 32, 32, 32)","(N, 32, 16, 16)","(N, 64, 16, 16)"],"a":2,"w":"Pooling halves height and width and leaves the channel count alone; the convolutions change the channels."},{"n":3,"ti":"Building a CNN","f":"03-building-a-cnn.html","lv":"Beginner","q":"Without augmentation the 4.2M-parameter MLP reached 99.4% training accuracy and 58.6% test accuracy. What does that show?","o":["It has enough capacity to memorise, but no structure that generalises across positions","It needed more epochs","The test set is mislabelled","MLPs cannot run on a GPU"],"a":0,"w":"Capacity is not the problem; the inductive bias is. The 308k-parameter CNN generalised to 85.8% on the same unaugmented data."},{"n":3,"ti":"Building a CNN","f":"03-building-a-cnn.html","lv":"Beginner","q":"What is the main practical advantage of a global average pooling head over flatten + linear?","o":["Much higher accuracy","It removes the need for convolutions","It trains without labels","It works for any input size and uses fewer parameters"],"a":3,"w":"Averaging each channel over the whole map gives a fixed-length vector whatever the image size. Here it matched flatten (87.6% vs 88.0%) with 19,200 fewer parameters."},{"n":3,"ti":"Building a CNN","f":"03-building-a-cnn.html","lv":"Beginner","q":"A convolution layer is translation…","o":["invariant: its output does not change when the input shifts","equivariant: its output shifts with the input","neither","invariant only with padding"],"a":1,"w":"Shift the input by 3 pixels and the output shifts by 3 (maximum difference 0.0 away from the borders). Invariance comes partly from pooling and the head."},{"n":3,"ti":"Building a CNN","f":"03-building-a-cnn.html","lv":"Beginner","q":"Shifting test images 8 pixels cost which model the least accuracy?","o":["The 1,024-wide MLP","The CNN with a flatten head","The CNN with global average pooling","They all lost the same"],"a":2,"w":"86.3% → 67.6% (−18.8 points), against −23.4 for the flatten head and −30.9 for the MLP. Global pooling ignores where features fired."},{"n":4,"ti":"Training a CNN on CIFAR-10","f":"04-training-a-cnn.html","lv":"Beginner","q":"Training and test accuracy are both 60% and close together after many epochs. What is the most likely diagnosis?","o":["Overfitting","Underfitting: the model or the optimisation is the limit","A data leak","Perfect training"],"a":1,"w":"No gap means the model is not memorising; low accuracy on both means it cannot fit well yet: more capacity, more epochs or a better learning rate."},{"n":4,"ti":"Training a CNN on CIFAR-10","f":"04-training-a-cnn.html","lv":"Beginner","q":"The linear scaling rule says that when the batch size doubles, the learning rate should…","o":["halve","stay the same","double","be multiplied by four"],"a":2,"w":"Twice the images per step and half the steps per epoch; doubling the rate keeps the movement per epoch similar. Here it broke above batch 256."},{"n":4,"ti":"Training a CNN on CIFAR-10","f":"04-training-a-cnn.html","lv":"Beginner","q":"Why is a learning-rate warm-up used at the start of training?","o":["Large early steps on random weights and unsettled BatchNorm statistics can push training somewhere it does not recover from","To save memory","To make the GPU warm up its clock","It is required by SGD"],"a":0,"w":"Early gradients are large and poorly aimed. Starting low and ramping up avoids divergence, which matters most for large learning rates and batches."},{"n":4,"ti":"Training a CNN on CIFAR-10","f":"04-training-a-cnn.html","lv":"Beginner","q":"On 5,000 images with no regularisation, test loss rose from 1.34 to 2.29 while test accuracy rose from 53% to 62%. How?","o":["A bug in the loss","The test set changed","Accuracy was measured on training data","More images became correct, while the remaining mistakes became more confident, which cross-entropy punishes heavily"],"a":3,"w":"Loss and accuracy measure different things. Overconfident errors raise cross-entropy even as the count of correct answers grows."},{"n":4,"ti":"Training a CNN on CIFAR-10","f":"04-training-a-cnn.html","lv":"Beginner","q":"Going from batch 128 to 2,048 on this GPU changed the time per epoch by about…","o":["16 times faster","10% faster","2 times faster","It became slower"],"a":1,"w":"15.7 s to 14.1 s for 10 epochs: the GPU was already busy at 128. The larger batch bought almost no speed and cost 36 points of accuracy."},{"n":5,"ti":"Data Augmentation","f":"05-data-augmentation.html","lv":"Beginner","q":"Adding cutout lowered training accuracy from 99.2% to 97.0% and raised test accuracy. Why is that a good sign?","o":["It means training was buggy","Lower training accuracy is always better","The model memorised less and generalised more: the train–test gap shrank","Cutout removes noisy labels"],"a":2,"w":"Regularisation makes memorisation harder. The gap fell from about 8 points to 5.2 while test accuracy rose to 91.8%."},{"n":5,"ti":"Data Augmentation","f":"05-data-augmentation.html","lv":"Beginner","q":"Why did Mixup and CutMix lower accuracy in 30-epoch runs?","o":["They make the task harder, so the model needs more epochs; it was still underfitting","They are incompatible with CNNs","They require colour images","They delete the labels"],"a":0,"w":"Training accuracy was only 94.7% and 93.2%. Their reported gains come from schedules of hundreds of epochs."},{"n":5,"ti":"Data Augmentation","f":"05-data-augmentation.html","lv":"Beginner","q":"For which dataset is a vertical flip a safe augmentation?","o":["Handwritten digits","Street scenes","Faces","Satellite images"],"a":3,"w":"Overhead images have no canonical up. For digits a flip can change the class; for street scenes and faces it creates unrealistic images."},{"n":5,"ti":"Data Augmentation","f":"05-data-augmentation.html","lv":"Beginner","q":"On an upside-down test set, the crop + flip model scored 42.5%. The model trained with vertical flips scored…","o":["About the same, 42%","88.6%, close to its normal accuracy","100%","10%"],"a":1,"w":"A model is robust to the transformations it was trained with, and to little else."},{"n":5,"ti":"Data Augmentation","f":"05-data-augmentation.html","lv":"Beginner","q":"With only 5,000 training images, crop + flip added how much accuracy?","o":["About 1 point","About 3 points","About 11 points","None"],"a":2,"w":"63.4% to 74.7%. With 50,000 images it added 3.4 points: augmentation matters most when data is scarce."},{"n":6,"ti":"Batch Norm & Normalisation Layers","f":"06-normalisation-layers.html","lv":"Beginner","q":"Over which dimensions does BatchNorm compute its mean for a (N, C, H, W) tensor?","o":["C, H and W, per image","H and W only","N, H and W, per channel","All four"],"a":2,"w":"One mean and variance per channel, over the batch and all spatial positions. GroupNorm and LayerNorm instead normalise each image on its own."},{"n":6,"ti":"Batch Norm & Normalisation Layers","f":"06-normalisation-layers.html","lv":"Beginner","q":"A BatchNorm model is evaluated in train mode with batch size 1. What happened to accuracy?","o":["It fell from 89% to about 10%","It stayed at 89%","It rose slightly","It raised an error"],"a":0,"w":"Each image is normalised by its own statistics, removing what distinguishes it. PyTorch only raises an error when a BN layer sees a single value per channel, such as after global pooling."},{"n":6,"ti":"Batch Norm & Normalisation Layers","f":"06-normalisation-layers.html","lv":"Beginner","q":"Why did a single train-mode pass over class-sorted test batches lower later eval-mode accuracy?","o":["It changed the weights","It changed γ and β","It deleted the running statistics","Train mode updates the running mean and variance, which absorbed the unrepresentative batches"],"a":3,"w":"No gradients flowed, but the running averages moved. Eval accuracy dropped from 89.0% to 77.7% and stayed there."},{"n":6,"ti":"Batch Norm & Normalisation Layers","f":"06-normalisation-layers.html","lv":"Beginner","q":"What does folding BatchNorm into the preceding convolution change?","o":["The model’s accuracy","Nothing about the outputs; it removes a layer, so inference is faster","It makes the model train faster","It converts the model to int8"],"a":1,"w":"In eval mode BN is a fixed affine map per channel, so W and b absorb it. Same accuracy within 0.05 points, 7% faster here."},{"n":6,"ti":"Batch Norm & Normalisation Layers","f":"06-normalisation-layers.html","lv":"Beginner","q":"Images in deployment are darker than in training. Which cheap step recovered most of the lost accuracy?","o":["Retraining with labels","Switching to train mode at inference","Re-estimating the BN running statistics on unlabelled darkened images","Increasing the batch size"],"a":2,"w":"85.3% → 88.2%, with no labels and no weight updates. Done on large, shuffled batches, then back to eval mode."},{"n":7,"ti":"Residual Networks","f":"07-residual-networks.html","lv":"Beginner","q":"A 56-layer plain CNN has higher training loss than a 20-layer one. What is this?","o":["Overfitting","The degradation problem: deeper plain networks are harder to optimise","Too much weight decay","A data bug"],"a":1,"w":"Overfitting would lower training loss. Here it rose from 0.166 to 0.485 with depth."},{"n":7,"ti":"Residual Networks","f":"07-residual-networks.html","lv":"Beginner","q":"When does a residual block need a 1 × 1 projection on its shortcut?","o":["Always","Only in the first block of the network","When it uses BatchNorm","When the block changes the number of channels or the spatial size"],"a":3,"w":"x and F(x) must have the same shape to be added. A 1 × 1 convolution with the block’s stride fixes both."},{"n":7,"ti":"Residual Networks","f":"07-residual-networks.html","lv":"Beginner","q":"What did the gradients of the plain 110-layer network look like at initialisation?","o":["The first layer’s gradient was millions of times larger than the last layer’s","All gradients were zero","Exactly the same as the residual network’s","Smaller at the first layer than the last"],"a":0,"w":"2.7 million against 0.6: an explosion, ratio 4.6 million. The residual-110 ratio was 1.8."},{"n":7,"ti":"Residual Networks","f":"07-residual-networks.html","lv":"Beginner","q":"Why is a bottleneck block cheaper than two 3 × 3 convolutions at 256 channels?","o":["It skips the convolution","It uses a larger stride","The 3 × 3 runs at 64 channels between two 1 × 1 convolutions","It has no BatchNorm"],"a":2,"w":"256·64 + 9·64·64 + 64·256 ≈ 70k multiply-adds per position, against about 1.18 million: 17 times fewer."},{"n":7,"ti":"Residual Networks","f":"07-residual-networks.html","lv":"Beginner","q":"With identical training, which scored highest on CIFAR-10 among the 6n + 2 networks?","o":["Plain-20","Residual-110","Plain-110","Residual-20"],"a":1,"w":"Residual-110 reached 91.38%. With skips, depth helped at every step; without them it hurt."},{"n":8,"ti":"Transfer Learning & Fine-Tuning","f":"08-transfer-learning.html","lv":"Beginner","q":"What does a linear probe train?","o":["Every layer, at a low learning rate","The last stage and the head","Only a linear layer on top of frozen features","Nothing; it uses the ImageNet head"],"a":2,"w":"The backbone is frozen; only a linear classifier on its 2,048-number features is trained. On Pets: 91.06% in 1.9 s."},{"n":8,"ti":"Transfer Learning & Fine-Tuning","f":"08-transfer-learning.html","lv":"Beginner","q":"Why did a ResNet-50 trained from scratch on 3,680 Pets photos reach only 41%?","o":["Far too few images for 23.6 M parameters to learn general visual features from nothing","The learning rate was zero","ResNet-50 cannot classify animals","The images were grayscale"],"a":0,"w":"Pretrained weights bring what 1.28 million ImageNet images taught; from scratch the model must learn edges and textures from 3,680 photos."},{"n":8,"ti":"Transfer Learning & Fine-Tuning","f":"08-transfer-learning.html","lv":"Beginner","q":"With two photos per breed (74 images), what did fine-tuning reach on the 37-breed test set?","o":["About 3%, chance","About 41%","About 93%","About 71%"],"a":3,"w":"71.11%; the linear probe reached 57.65%. Chance on 37 classes is 2.7%."},{"n":8,"ti":"Transfer Learning & Fine-Tuning","f":"08-transfer-learning.html","lv":"Beginner","q":"Why does ImageNet transfer so well to Oxford Pets in particular?","o":["Pets is a subset of ImageNet","ImageNet already contains many dog breeds and cats, so its features are close to what the task needs","Pets images are larger","Pets has more classes"],"a":1,"w":"The images differ, but ImageNet’s 1,000 classes include 120 dog breeds and several cats, so fine-grained animal features are already learned."},{"n":8,"ti":"Transfer Learning & Fine-Tuning","f":"08-transfer-learning.html","lv":"Beginner","q":"In what order is it usually sensible to try transfer methods?","o":["From scratch, then fine-tune, then probe","Full fine-tune only","Linear probe, then last stage, then full fine-tune","Probe only, never fine-tune"],"a":2,"w":"Each step costs more; the probe is a seconds-long baseline, and fine-tuning is worth it when it beats that baseline."},{"n":9,"ti":"Evaluating Image Classifiers","f":"09-evaluating-classifiers.html","lv":"Beginner","q":"A model’s mean confidence is 96% and its accuracy is 93%. It is…","o":["perfectly calibrated","underconfident","overconfident","overfitting the validation set"],"a":2,"w":"It claims more certainty than it earns. Temperature scaling with T > 1 (1.57 here) softens it."},{"n":9,"ti":"Evaluating Image Classifiers","f":"09-evaluating-classifiers.html","lv":"Beginner","q":"What does temperature scaling change?","o":["Only the confidence; every predicted class stays the same","The predicted classes and the accuracy","The model’s weights","The training data"],"a":0,"w":"Dividing logits by a positive T preserves their order, so argmax is unchanged."},{"n":9,"ti":"Evaluating Image Classifiers","f":"09-evaluating-classifiers.html","lv":"Beginner","q":"On which data should the temperature be fitted?","o":["The training set","The test set","CIFAR-10.1","A held-out validation set"],"a":3,"w":"Training data is overfit (too confident); fitting on the test set makes the test score optimistic. Here 5,000 held-out training images were used."},{"n":9,"ti":"Evaluating Image Classifiers","f":"09-evaluating-classifiers.html","lv":"Beginner","q":"The ResNet-18 scored 92.9% on CIFAR-10’s test set. On CIFAR-10.1, built the same way years later, it scored…","o":["About the same","85.2%","50%","Higher"],"a":1,"w":"A 7.7-point drop, in line with published models: a small distribution shift between the two collections."},{"n":9,"ti":"Evaluating Image Classifiers","f":"09-evaluating-classifiers.html","lv":"Beginner","q":"Which corruption hurt the model most at its “medium” level?","o":["Brightness +80","Contrast ×0.4","A 3-pixel blur","JPEG quality 20"],"a":2,"w":"Blur 51.65% (and noise σ = 16, 54.39%), against 85.9% for brightness and 83.1% for contrast, which resemble training augmentations."},{"n":10,"ti":"What a CNN Sees: Feature Maps & Grad-CAM","f":"10-what-a-cnn-sees.html","lv":"Beginner","q":"Why can first-layer filters be drawn as images but deeper filters cannot?","o":["Deeper filters are too large","First-layer filters act on RGB pixels; deeper ones act on dozens or hundreds of abstract channels","Deeper filters are random","Only the first layer is trained"],"a":1,"w":"A 7 × 7 × 3 filter is a tiny colour image. A 3 × 3 × 512 filter has no colour interpretation; we visualise what it responds to instead."},{"n":10,"ti":"What a CNN Sees: Feature Maps & Grad-CAM","f":"10-what-a-cnn-sees.html","lv":"Beginner","q":"How does Grad-CAM weight each feature map of the last convolutional stage?","o":["Equally","By its largest activation","By the input pixel gradients","By the average gradient of the class score with respect to that map"],"a":3,"w":"The spatially averaged gradient is the channel’s importance for that class; the weighted sum, kept positive, is the heat map."},{"n":10,"ti":"What a CNN Sees: Feature Maps & Grad-CAM","f":"10-what-a-cnn-sees.html","lv":"Beginner","q":"Why is Grad-CAM on ResNet-50 coarse?","o":["It is computed on the 7 × 7 last stage and upsampled","It uses only one channel","It is computed on the first layer","It ignores gradients"],"a":0,"w":"Each of the 49 cells covers a 32-pixel step of the 224 × 224 input (Chapter 2’s jump of 32)."},{"n":10,"ti":"What a CNN Sees: Feature Maps & Grad-CAM","f":"10-what-a-cnn-sees.html","lv":"Beginner","q":"After training with a magenta square on every bird, how many unstamped test birds did the model recognise?","o":["About 80%","About 50%","None","All of them"],"a":2,"w":"0.0%: it had learned the square, not birds. Stamped non-birds were called “bird” 81.9% of the time."},{"n":10,"ti":"What a CNN Sees: Feature Maps & Grad-CAM","f":"10-what-a-cnn-sees.html","lv":"Beginner","q":"The shortcut model scored 80.7% overall. Why is that dangerous?","o":["80% is too low to deploy","It looks like an ordinary weaker model, hiding a complete failure on one class","It means the model is overfitting","It proves the data is mislabelled"],"a":1,"w":"Averages hide shortcuts. Per-class results, heat maps and tests that add or remove the cue reveal them."},{"n":11,"ti":"CNN Architectures: VGG to ConvNeXt","f":"11-cnn-architectures.html","lv":"Intermediate","q":"How much did torchvision’s modern (V2) training recipe add to ResNet-50’s ImageNet top-1?","o":["0.5 points","About 1.5 points","4.8 points","15 points"],"a":2,"w":"76.1% (V1) to 80.9% (V2), with the same architecture: more than separates most architectures in the table."},{"n":11,"ti":"CNN Architectures: VGG to ConvNeXt","f":"11-cnn-architectures.html","lv":"Intermediate","q":"VGG-16 has 31 GFLOPs yet was among the fastest models on the GPU at batch 1. Why?","o":["Few, large, regular 3 × 3 layers that tensor cores run at full speed, and few kernel launches","It has the fewest parameters","It skips most of its layers at inference","It runs at lower resolution"],"a":0,"w":"At batch 1 the GPU is underused, so layer count and regularity matter more than FLOPs. On the CPU it was the slowest (42.5 ms)."},{"n":11,"ti":"CNN Architectures: VGG to ConvNeXt","f":"11-cnn-architectures.html","lv":"Intermediate","q":"What is the Pareto front in a cost-versus-accuracy plot?","o":["The most accurate model","The cheapest model","The average of all models","The models for which no other model is both cheaper and more accurate"],"a":3,"w":"Anything off the front is dominated: some other model beats it on both axes, so it is never the right choice for that pair."},{"n":11,"ti":"CNN Architectures: VGG to ConvNeXt","f":"11-cnn-architectures.html","lv":"Intermediate","q":"Which idea did ConvNeXt borrow from vision transformers?","o":["Attention between patches","Large depthwise kernels, LayerNorm, GELU and the AdamW training recipe","A class token","Positional embeddings"],"a":1,"w":"It stays fully convolutional, but adopts transformer-era design choices and training, and reached 82.5% top-1."},{"n":11,"ti":"CNN Architectures: VGG to ConvNeXt","f":"11-cnn-architectures.html","lv":"Intermediate","q":"Which family dominated CPU latency at batch 1 here?","o":["VGG","DenseNet","MobileNet and EfficientNet-B0","ResNet-101"],"a":2,"w":"5.4–6.9 ms on 8 threads, against 15.2 for ResNet-50 and 42.5 for VGG-16: on CPUs, FLOPs translate into time."},{"n":12,"ti":"Efficient Convolutions","f":"12-efficient-convolutions.html","lv":"Intermediate","q":"How many weights does a depthwise 3 × 3 convolution on 64 channels have?","o":["36,864","576","4,096","64"],"a":1,"w":"One 3 × 3 kernel per channel: 9 × 64. A standard 3 × 3 from 64 to 64 channels has 9 × 64 × 64 = 36,864."},{"n":12,"ti":"Efficient Convolutions","f":"12-efficient-convolutions.html","lv":"Intermediate","q":"A depthwise layer did 64× fewer FLOPs than a standard one but ran only 3× faster on the GPU. Why?","o":["The GPU does not support depthwise convolutions","bf16 was not used","The FLOP count was wrong","It is memory-bound: little arithmetic per byte read and written, so bandwidth sets the time"],"a":3,"w":"9 multiply-adds per output cannot keep tensor cores busy; the layer ran at 3.1 TFLOPS against 62.5 for the dense one."},{"n":12,"ti":"Efficient Convolutions","f":"12-efficient-convolutions.html","lv":"Intermediate","q":"Where did MobileNet’s FLOP savings turn into the biggest speed-up over ResNet-18?","o":["On one CPU thread at batch 1","On the GPU at batch 1","On the GPU at batch 64","Nowhere"],"a":0,"w":"9.5 ms against 27.6 ms on one core (2.9×). On the GPU at batch 1 MobileNet v2 was 2.3× slower."},{"n":12,"ti":"Efficient Convolutions","f":"12-efficient-convolutions.html","lv":"Intermediate","q":"What is “inverted” about MobileNet v2’s inverted residual?","o":["It subtracts the input instead of adding it","It runs backwards","It goes narrow → wide → narrow, the opposite of ResNet’s wide → narrow → wide bottleneck","It has no activation"],"a":2,"w":"A 1 × 1 expands channels (×6), a depthwise 3 × 3 filters the wide tensor, a 1 × 1 projects back; the residual joins the narrow ends."},{"n":12,"ti":"Efficient Convolutions","f":"12-efficient-convolutions.html","lv":"Intermediate","q":"What is the right way to choose between two architectures for a phone app?","o":["Pick the one with fewer FLOPs","Measure latency on the target phone at the real batch size, alongside accuracy","Pick the one with fewer parameters","Benchmark both on a server GPU"],"a":1,"w":"Rankings changed between GPU and CPU and between batch sizes here. Only measurement on the target settles it."},{"n":13,"ti":"Detection Basics: Boxes, IoU, Anchors & NMS","f":"13-detection-basics.html","lv":"Intermediate","q":"Two equal boxes overlap by half their width. What is their IoU?","o":["0.5","1/3","0.25","2/3"],"a":1,"w":"Intersection is half a box; the union is one and a half boxes: 0.5 / 1.5 = 1/3."},{"n":13,"ti":"Detection Basics: Boxes, IoU, Anchors & NMS","f":"13-detection-basics.html","lv":"Intermediate","q":"Why is predicting log(w_gt / w_anchor) better than predicting the width in pixels?","o":["It is a small, scale-independent number the same head can predict at every position","It is faster to compute","It removes the need for NMS","It makes IoU larger"],"a":0,"w":"Relative, log-scaled targets are near zero for good anchors whatever the object’s size, which makes regression much easier to learn."},{"n":13,"ti":"Detection Basics: Boxes, IoU, Anchors & NMS","f":"13-detection-basics.html","lv":"Intermediate","q":"What happened to person AP when NMS was switched off in Faster R-CNN?","o":["It rose slightly","It stayed about the same","It fell to zero","It fell from about 60.6 to 18.4"],"a":3,"w":"The top 100 boxes per image were mostly duplicates, each counted as a false positive."},{"n":13,"ti":"Detection Basics: Boxes, IoU, Anchors & NMS","f":"13-detection-basics.html","lv":"Intermediate","q":"Why use batched_nms instead of one NMS over all boxes?","o":["It is more accurate within a class","It sorts boxes differently","So boxes of different classes never suppress each other","It avoids computing IoU"],"a":2,"w":"A person on a bicycle has heavily overlapping boxes of two classes; both should survive."},{"n":13,"ti":"Detection Basics: Boxes, IoU, Anchors & NMS","f":"13-detection-basics.html","lv":"Intermediate","q":"With one 128-pixel square anchor size, what share of COCO objects had an anchor at IoU ≥ 0.5?","o":["86%","About 15%","50%","100%"],"a":1,"w":"14.6%. Five sizes on FPN levels with three aspect ratios raised it to 86.1%."},{"n":14,"ti":"Two-Stage Detectors: Faster R-CNN","f":"14-two-stage-detectors.html","lv":"Intermediate","q":"What does Faster R-CNN’s region proposal network output?","o":["Final class labels for every object","A segmentation mask","About 1,000 class-agnostic candidate boxes with objectness scores","One box per anchor, all kept"],"a":2,"w":"It scores every anchor as object or background, refines the boxes, applies NMS and keeps the top proposals for the second stage."},{"n":14,"ti":"Two-Stage Detectors: Faster R-CNN","f":"14-two-stage-detectors.html","lv":"Intermediate","q":"From which FPN level is a 56 × 56-pixel region pooled?","o":["P2 (stride 4)","P3 (stride 8)","P4 (stride 16)","P5 (stride 32)"],"a":0,"w":"k = ⌊4 + log₂(56/224)⌋ = ⌊4 − 2⌋ = 2. Small regions use the finest map."},{"n":14,"ti":"Two-Stage Detectors: Faster R-CNN","f":"14-two-stage-detectors.html","lv":"Intermediate","q":"Why does RoI Align beat RoI Pool?","o":["It uses more bins","It is faster","It uses average instead of max pooling","It avoids rounding the box and bins to the grid, sampling exact positions bilinearly"],"a":3,"w":"Measured: 21.6 px mean misplacement for RoI Pool, 0.0 for RoI Align on a linear feature map."},{"n":14,"ti":"Two-Stage Detectors: Faster R-CNN","f":"14-two-stage-detectors.html","lv":"Intermediate","q":"Where did most of Faster R-CNN v2’s 32 ms per image go?","o":["Resizing the image","About 14 ms in the backbone and FPN, the rest in the RPN and RoI heads","Almost all in NMS","Copying to the GPU"],"a":1,"w":"Backbone + FPN 13.6 ms, RPN 8.1, RoI heads 9.6: the two-stage machinery cost more than the backbone."},{"n":14,"ti":"Two-Stage Detectors: Faster R-CNN","f":"14-two-stage-detectors.html","lv":"Intermediate","q":"Fine-tuned on 120 pedestrian photos, which start gave 99% AP50 after one epoch?","o":["Random weights","An ImageNet backbone with new heads","The full COCO-trained detector with a new box predictor","None reached 99%"],"a":2,"w":"The COCO detector already detects people. From an ImageNet backbone only, it reached 46.1 after ten epochs."},{"n":15,"ti":"One-Stage Detectors: YOLO, RetinaNet & Anchor-Free","f":"15-one-stage-detectors.html","lv":"Intermediate","q":"With plain cross-entropy, where did most of RetinaNet’s classification loss come from?","o":["Foreground anchors","Easy background anchors, by sheer number","Ignored anchors","The box regression"],"a":1,"w":"85.3%: each easy background anchor has a tiny loss, but there were 8.4 million of them in 50 images."},{"n":15,"ti":"One-Stage Detectors: YOLO, RetinaNet & Anchor-Free","f":"15-one-stage-detectors.html","lv":"Intermediate","q":"With γ = 2, how much less does an example with p_t = 0.9 contribute under focal loss than under cross-entropy?","o":["2 times","10 times","It contributes more","100 times"],"a":3,"w":"(1 − 0.9)² = 0.01: a hundredth of its cross-entropy."},{"n":15,"ti":"One-Stage Detectors: YOLO, RetinaNet & Anchor-Free","f":"15-one-stage-detectors.html","lv":"Intermediate","q":"Why is RetinaNet’s classification bias initialised so that p = 0.01?","o":["So millions of background anchors do not produce a huge loss in the first iterations","To make the model predict more objects","Because focal loss requires it mathematically","To speed up inference"],"a":0,"w":"At p = 0.5 every background anchor would start with a large loss, destabilising early training."},{"n":15,"ti":"One-Stage Detectors: YOLO, RetinaNet & Anchor-Free","f":"15-one-stage-detectors.html","lv":"Intermediate","q":"What does an FCOS location regress instead of anchor offsets?","o":["A heat map","The box’s area","The four distances to the box’s left, top, right and bottom edges","Nothing; it only classifies"],"a":2,"w":"Plus a centre-ness score that down-weights predictions from near the box edges."},{"n":15,"ti":"One-Stage Detectors: YOLO, RetinaNet & Anchor-Free","f":"15-one-stage-detectors.html","lv":"Intermediate","q":"Why did SSDlite score only 2.5 AP on small objects?","o":["It has no box regression","It works on 320-pixel inputs, so small objects are only a few pixels across","It uses focal loss","It was trained on a different dataset"],"a":1,"w":"Resizing a 640-pixel image to 320 halves every object; a 20-pixel object becomes 10 pixels, below what its features resolve."},{"n":16,"ti":"Evaluating Detectors: mAP from Scratch","f":"16-evaluating-detectors.html","lv":"Intermediate","q":"A second detection of an object that has already been matched is counted as…","o":["a true positive","ignored","a false positive","a false negative"],"a":2,"w":"Each ground-truth box can be matched once; duplicates lower precision, which is why NMS matters for AP."},{"n":16,"ti":"Evaluating Detectors: mAP from Scratch","f":"16-evaluating-detectors.html","lv":"Intermediate","q":"What does COCO’s AP@[.5:.95] average over?","o":["Ten IoU thresholds from 0.50 to 0.95, and over classes","Ten score thresholds","Ten random subsets of images","Precision at ten recall levels only"],"a":0,"w":"Each threshold gets its own 101-point AP per class; the reported AP is the mean of all of them."},{"n":16,"ti":"Evaluating Detectors: mAP from Scratch","f":"16-evaluating-detectors.html","lv":"Intermediate","q":"What does interpolating precision in the PR curve do?","o":["Averages precision over images","Removes false positives","Smooths the curve with a moving average","Replaces precision at each recall by the best precision at that recall or higher"],"a":3,"w":"It makes the curve non-increasing, so AP does not depend on small wiggles in the ranking."},{"n":16,"ti":"Evaluating Detectors: mAP from Scratch","f":"16-evaluating-detectors.html","lv":"Intermediate","q":"Keeping only detections scoring above 0.5 changed Faster R-CNN’s AP how?","o":["Raised it, by removing false positives","Lowered it from 51.3 to 49.0, by cutting off the high-recall end of the curve","No change","Lowered it to about 20"],"a":1,"w":"AP integrates over all thresholds; truncating the list removes recall it could have earned."},{"n":16,"ti":"Evaluating Detectors: mAP from Scratch","f":"16-evaluating-detectors.html","lv":"Intermediate","q":"How are detections that overlap a crowd (iscrowd) region treated by COCO evaluation?","o":["As false positives","As true positives","Ignored: neither rewarded nor penalised","Counted twice"],"a":2,"w":"A crowd region marks many unannotated people; detections inside it are ignored, and one crowd region can absorb several."},{"n":17,"ti":"Semantic Segmentation: FCN & U-Net","f":"17-semantic-segmentation.html","lv":"Intermediate","q":"What makes a network “fully convolutional”?","o":["It has more convolution layers","It uses only 1 × 1 convolutions","It has no fully connected layers, so it outputs a spatial map of predictions for any input size","It has no pooling"],"a":2,"w":"The dense classifier is replaced by a 1 × 1 convolution, so every position of the final map gets its own class scores."},{"n":17,"ti":"Semantic Segmentation: FCN & U-Net","f":"17-semantic-segmentation.html","lv":"Intermediate","q":"Where did U-Net’s skip connections help most in the pet experiment?","o":["On the thin border class and pixels near the outline","On the background class","They made training faster","They did not help"],"a":0,"w":"Border IoU 46.2 → 53.2 and boundary accuracy 79.3% → 84.3%: skips carry the precise positions the decoder had lost."},{"n":17,"ti":"Semantic Segmentation: FCN & U-Net","f":"17-semantic-segmentation.html","lv":"Intermediate","q":"Predicting “background” for every pixel scored 57.7% pixel accuracy. What was its mean IoU?","o":["57.7","50","0","About 19"],"a":3,"w":"IoU 57.7 for background and 0 for pet and border: averaged over three classes, 19.2."},{"n":17,"ti":"Semantic Segmentation: FCN & U-Net","f":"17-semantic-segmentation.html","lv":"Intermediate","q":"How does DeepLab keep high-resolution features without an encoder–decoder?","o":["By using larger input images","By replacing late strides with dilated convolutions, so the receptive field grows without downsampling","By removing all convolutions","By training longer"],"a":1,"w":"Its output stays at 1/8 resolution instead of 1/32, and parallel dilation rates gather context at several scales."},{"n":17,"ti":"Semantic Segmentation: FCN & U-Net","f":"17-semantic-segmentation.html","lv":"Intermediate","q":"How should a label mask be resized?","o":["Bilinear interpolation","Bicubic interpolation","Nearest neighbour","Antialiased bilinear"],"a":2,"w":"Labels are categories; interpolating between class 0 and class 2 invents a class 1. Nearest only copies existing labels."},{"n":18,"ti":"Instance Segmentation & Keypoints","f":"18-instance-segmentation-and-keypoints.html","lv":"Intermediate","q":"Two people stand touching. What does semantic segmentation output for them?","o":["Two masks","One “person” region","Two boxes","Nothing, people are stuff"],"a":1,"w":"Semantic segmentation has a class per pixel but no notion of instances; separating them needs instance or panoptic segmentation."},{"n":18,"ti":"Instance Segmentation & Keypoints","f":"18-instance-segmentation-and-keypoints.html","lv":"Intermediate","q":"Why does Mask R-CNN predict masks with a per-class sigmoid instead of a softmax over classes?","o":["Sigmoid is faster","Softmax cannot be used for pixels","To make masks overlap","So classes do not compete inside the mask: the box classifier picks the class and the mask head only decides which pixels"],"a":3,"w":"Decoupling “what” from “where” was one of the paper’s key findings; a softmax across classes did worse."},{"n":18,"ti":"Instance Segmentation & Keypoints","f":"18-instance-segmentation-and-keypoints.html","lv":"Intermediate","q":"Where was the gap between box AP and mask AP largest in the measurement?","o":["On small objects and at strict IoU (0.75)","On large objects","At IoU 0.5","There was no gap"],"a":0,"w":"Small 36.6 → 28.4 and AP75 57.5 → 51.4, but large 64.7 → 63.1: a fixed 28 × 28 mask is the bottleneck for fine outlines."},{"n":18,"ti":"Instance Segmentation & Keypoints","f":"18-instance-segmentation-and-keypoints.html","lv":"Intermediate","q":"What does OKS normalise the keypoint error by?","o":["The image size","The number of keypoints only","The person’s scale and a per-joint tolerance","The detector’s score"],"a":2,"w":"exp(−d² / (2s²k²)): s is the square root of the person’s area and k reflects how precisely annotators can place that joint."},{"n":18,"ti":"Instance Segmentation & Keypoints","f":"18-instance-segmentation-and-keypoints.html","lv":"Intermediate","q":"A panoptic model finds every object but its outlines are rough. Which factor of PQ drops?","o":["RQ, recognition quality","SQ, segmentation quality (mean IoU of matched segments)","Neither","Both equally"],"a":1,"w":"Matches still clear IoU 0.5, so RQ stays high; their average IoU falls, which is SQ."},{"n":19,"ti":"Vision Transformers from Scratch","f":"19-vision-transformers.html","lv":"Intermediate","q":"How many patch tokens does ViT-B/16 make from a 224 × 224 image?","o":["16","224","196","768"],"a":2,"w":"224 / 16 = 14 per side, 14 × 14 = 196; with the class token the sequence has 197."},{"n":19,"ti":"Vision Transformers from Scratch","f":"19-vision-transformers.html","lv":"Intermediate","q":"The patch embedding is equivalent to which layer?","o":["A convolution with a 16 × 16 kernel and stride 16","A 3 × 3 convolution with stride 1","Max pooling","An attention layer"],"a":0,"w":"Non-overlapping patches, each projected by the same linear map: that is a strided convolution, which matched unfold + matmul here to rounding error."},{"n":19,"ti":"Vision Transformers from Scratch","f":"19-vision-transformers.html","lv":"Intermediate","q":"Why does a ViT need position embeddings?","o":["To normalise the patches","To reduce the number of tokens","To make attention faster","Self-attention treats its input as a set, so without them the model cannot tell where a patch came from"],"a":3,"w":"Shuffle the patches and attention gives the same outputs, shuffled. Positions break that symmetry."},{"n":19,"ti":"Vision Transformers from Scratch","f":"19-vision-transformers.html","lv":"Intermediate","q":"Where are most of ViT-B/16’s parameters?","o":["The position embeddings","The MLPs inside the blocks, about two thirds","The patch embedding","The classifier head"],"a":1,"w":"56.7 M of 86.6 M are MLP weights; attention projections are 28.3 M."},{"n":19,"ti":"Vision Transformers from Scratch","f":"19-vision-transformers.html","lv":"Intermediate","q":"You double the input side from 224 to 448 with the same patch size. Roughly how does attention’s score-matrix size change?","o":["Doubles","Quadruples","Grows about 16 times","Stays the same"],"a":2,"w":"Tokens grow 4× (twice per side), and the T × T matrix grows with the square: about 16×."},{"n":20,"ti":"Training ViTs: Data, DeiT & ViT vs CNN","f":"20-training-vits.html","lv":"Intermediate","q":"Which inductive bias does a CNN have that a ViT largely lacks?","o":["Using a softmax classifier","Locality: each layer only combines neighbouring positions","Using residual connections","Using normalisation layers"],"a":1,"w":"Both use residuals and normalisation. Only the CNN restricts each layer to a small neighbourhood; ViT attention is global from block 1."},{"n":20,"ti":"Training ViTs: Data, DeiT & ViT vs CNN","f":"20-training-vits.html","lv":"Intermediate","q":"What happened to ResNet-18’s lead over the ViT as the training set grew from 5k to 50k images?","o":["It grew","It stayed the same","The ViT overtook it","It shrank, from 23.4 to 12.0 points"],"a":3,"w":"The ViT gained 25.3 points from 10× more data, the ResNet 13.9: the ViT has more to learn from data."},{"n":20,"ti":"Training ViTs: Data, DeiT & ViT vs CNN","f":"20-training-vits.html","lv":"Intermediate","q":"Why were the smaller subsets trained for more epochs?","o":["To give every size the same number of optimiser steps, so small sets are not under-trained","To make the ViT win","Because small sets need less regularisation","By mistake"],"a":0,"w":"At equal epochs, 5,000 images would get a tenth of the updates of 50,000, mixing up “less data” with “less training”. (Here the 5,000 set was capped at 300 epochs, half the steps of the others.)"},{"n":20,"ti":"Training ViTs: Data, DeiT & ViT vs CNN","f":"20-training-vits.html","lv":"Intermediate","q":"What was DeiT’s main change relative to the original ViT?","o":["A convolutional stem","A bigger model","The training recipe: strong augmentation, Mixup/CutMix, label smoothing, long schedules","Pre-training on JFT-300M"],"a":2,"w":"Same ViT-B architecture, ImageNet-1k only: 81.8% against the original’s 77.9%."},{"n":20,"ti":"Training ViTs: Data, DeiT & ViT vs CNN","f":"20-training-vits.html","lv":"Intermediate","q":"Halving the patch size at a fixed input resolution multiplies the number of tokens by about…","o":["2","4","8","16"],"a":1,"w":"Patches per side double, so tokens quadruple; attention cost then grows about 16×."},{"n":21,"ti":"Swin & DETR","f":"21-swin-and-detr.html","lv":"Intermediate","q":"Why does Swin shift its windows in alternate blocks?","o":["To reduce the number of parameters","So information can cross window boundaries; otherwise windows would never exchange information","To downsample the image","To add position information"],"a":1,"w":"With fixed windows, tokens in different windows never meet. Shifting by half a window puts boundary tokens together in the next block."},{"n":21,"ti":"Swin & DETR","f":"21-swin-and-detr.html","lv":"Intermediate","q":"How does window attention’s cost grow with the number of tokens T, for a fixed window size?","o":["T²","T³","It is constant","Linearly in T"],"a":3,"w":"Each token attends to a fixed 49 others: T × 49 scores. Global attention has T × T."},{"n":21,"ti":"Swin & DETR","f":"21-swin-and-detr.html","lv":"Intermediate","q":"At 224 pixels, which was faster in the measurement: Swin-T (28 M params) or ViT-B/16 (87 M)?","o":["ViT-B/16, 3.9 ms against 6.4 ms","Swin-T, by a wide margin","They were identical","Swin-T ran out of memory"],"a":0,"w":"Few large matrix multiplies use a GPU better than many small windowed ones. Swin overtook from 448 pixels and was 8.5× faster at 896."},{"n":21,"ti":"Swin & DETR","f":"21-swin-and-detr.html","lv":"Intermediate","q":"In DETR training, what happens to a prediction that is not matched to any true object?","o":["It is ignored","It is removed by NMS","It is trained to predict “no object”","It is matched to the nearest object anyway"],"a":2,"w":"That is what suppresses duplicates: a second prediction on an object is pushed to “no object” by the loss."},{"n":21,"ti":"Swin & DETR","f":"21-swin-and-detr.html","lv":"Intermediate","q":"What did adding NMS do to DETR’s AP on the 500 COCO images?","o":["Raised it by 3 points","Lowered it by 1.0 point","No change","It became 0"],"a":1,"w":"45.4 → 44.4: DETR’s overlapping boxes were mostly real neighbouring objects, and NMS deleted some."},{"n":22,"ti":"Self-Supervised Learning: SimCLR & MoCo","f":"22-contrastive-self-supervised.html","lv":"Intermediate","q":"In SimCLR, what is a positive pair?","o":["Two images of the same class","Two augmented views of the same image","An image and its label","Two neighbouring images in the dataset"],"a":1,"w":"No labels are used: the only “same” relation is two views of one photo. Images of the same class in the batch count as negatives."},{"n":22,"ti":"Self-Supervised Learning: SimCLR & MoCo","f":"22-contrastive-self-supervised.html","lv":"Intermediate","q":"What does a smaller temperature τ do in InfoNCE?","o":["Makes all negatives count equally","Removes the need for negatives","Sharpens the softmax, so the loss focuses on the hardest (most similar) negatives","Increases the batch size"],"a":2,"w":"Dividing similarities by a small τ magnifies their differences; the largest negatives dominate the denominator."},{"n":22,"ti":"Self-Supervised Learning: SimCLR & MoCo","f":"22-contrastive-self-supervised.html","lv":"Intermediate","q":"How does MoCo get many negatives without a huge batch?","o":["A queue of past projections, encoded by a slowly updated momentum encoder","By using labels","By making more augmentations per image","By training for more epochs"],"a":0,"w":"The queue holds tens of thousands of keys; the momentum encoder keeps them consistent as the main encoder changes."},{"n":22,"ti":"Self-Supervised Learning: SimCLR & MoCo","f":"22-contrastive-self-supervised.html","lv":"Intermediate","q":"What does a linear probe measure?","o":["How fast the encoder runs","The contrastive loss on test data","The accuracy after fine-tuning the whole network","How well a linear classifier trained on the frozen features separates the classes"],"a":3,"w":"Only the linear layer is trained, so the score reflects the features themselves."},{"n":22,"ti":"Self-Supervised Learning: SimCLR & MoCo","f":"22-contrastive-self-supervised.html","lv":"Intermediate","q":"With only 1% of CIFAR-10’s labels (500 images), which did better in the measurement?","o":["A ResNet-18 trained from scratch on the 500 images","A linear probe on SimCLR features (66.0% against 42.7%)","They were equal","Neither beat chance"],"a":1,"w":"The features were learned from all 50,000 unlabelled images; the 500 labels only had to train a linear layer."},{"n":23,"ti":"Masked Autoencoders & DINO","f":"23-mae-and-dino.html","lv":"Intermediate","q":"Why does MAE mask 75% of patches rather than 15% like BERT?","o":["To save memory in the decoder","Because images have fewer patches than sentences have words","Images are so redundant that low masking can be solved by interpolating neighbours","To make reconstructions sharper"],"a":2,"w":"At 25% masking the loss was 0.11: the gaps are easy to fill from neighbours. A high ratio forces the encoder to model content."},{"n":23,"ti":"Masked Autoencoders & DINO","f":"23-mae-and-dino.html","lv":"Intermediate","q":"What does MAE’s encoder process during pre-training?","o":["Only the visible patches, with no mask tokens","All patches, with mask tokens in the hidden positions","The reconstructed image","Only the hidden patches"],"a":0,"w":"Mask tokens are added only before the small decoder; the large encoder works on 25% of the tokens."},{"n":23,"ti":"Masked Autoencoders & DINO","f":"23-mae-and-dino.html","lv":"Intermediate","q":"How are DINO’s teacher weights updated?","o":["By gradient descent on a separate loss","They are frozen ImageNet weights","They are copied from the student every step","As an exponential moving average of the student’s weights"],"a":3,"w":"Momentum close to 1 gives a slowly changing, stable teacher, as in MoCo’s key encoder."},{"n":23,"ti":"Masked Autoencoders & DINO","f":"23-mae-and-dino.html","lv":"Intermediate","q":"What prevents DINO from collapsing to the same output for every image?","o":["Negative pairs","Centring and sharpening the teacher’s output","A reconstruction loss","Labels"],"a":1,"w":"Centring discourages one dominant dimension, sharpening discourages a uniform output; together they force image-dependent outputs."},{"n":23,"ti":"Masked Autoencoders & DINO","f":"23-mae-and-dino.html","lv":"Intermediate","q":"What is the main lesson of the frozen-feature comparison?","o":["Supervised pre-training is always best","MAE is always best","Rankings depend on the task and the evaluation, so test on your own data","All methods are identical"],"a":2,"w":"The order changed between datasets and between linear and kNN evaluation."},{"n":24,"ti":"CLIP & Zero-Shot Vision","f":"24-clip-and-zero-shot.html","lv":"Intermediate","q":"What plays the role of the negatives in CLIP’s training?","o":["Augmented crops of the same image","The other captions (and images) in the batch","Randomly generated text","Images with the wrong labels"],"a":1,"w":"Each image must pick its own caption out of all N in the batch; the other N − 1 are negatives, and the same holds the other way."},{"n":24,"ti":"CLIP & Zero-Shot Vision","f":"24-clip-and-zero-shot.html","lv":"Intermediate","q":"In zero-shot CLIP classification, what are the classifier’s weights?","o":["Learned on the target dataset","Copied from an ImageNet classifier","Random","The normalised text embeddings of one sentence (or an ensemble of sentences) per class"],"a":3,"w":"Nothing is trained; the text encoder writes the classifier."},{"n":24,"ti":"CLIP & Zero-Shot Vision","f":"24-clip-and-zero-shot.html","lv":"Intermediate","q":"Why does prompt ensembling help?","o":["Averaging several wordings smooths out the quirks of any single template","It trains the text encoder","It increases the image resolution","It removes the need for class names"],"a":0,"w":"Each template’s embedding has noise unrelated to the class; the mean keeps what they share."},{"n":24,"ti":"CLIP & Zero-Shot Vision","f":"24-clip-and-zero-shot.html","lv":"Intermediate","q":"What is a typographic attack on CLIP?","o":["Misspelling the class names in the prompts","Changing the font of the captions during training","Writing another class’s name on the image so the model reads it instead of looking","Adding invisible noise to the pixels"],"a":2,"w":"Captions often mention visible text, so CLIP learned to read; a handwritten label can win over the object."},{"n":24,"ti":"CLIP & Zero-Shot Vision","f":"24-clip-and-zero-shot.html","lv":"Intermediate","q":"Which task is CLIP known to be weak at?","o":["Recognising common objects","Counting objects and spatial relations","Matching captions to photos","Recognising animals"],"a":1,"w":"Captions rarely state counts or positions precisely, so “three dogs” and “five dogs” embed close together."},{"n":25,"ti":"Foundation Models: SAM & Open-Vocabulary Detection","f":"25-sam-and-open-vocabulary.html","lv":"Advanced","q":"Why does SAM return three masks for a single click?","o":["To vote and average them","Because it runs three encoders","A single point is ambiguous (part, object, whole), so it offers each interpretation with a predicted IoU","For three different classes"],"a":2,"w":"A click on a shirt may mean the shirt, the person or the person plus bicycle; averaging would blur them together."},{"n":25,"ti":"Foundation Models: SAM & Open-Vocabulary Detection","f":"25-sam-and-open-vocabulary.html","lv":"Advanced","q":"Which part of SAM runs once per image?","o":["The ViT image encoder","The prompt encoder","The mask decoder","All of them, for each click"],"a":0,"w":"Its embedding is cached; the decoder answers each prompt from it."},{"n":25,"ti":"Foundation Models: SAM & Open-Vocabulary Detection","f":"25-sam-and-open-vocabulary.html","lv":"Advanced","q":"What does SAM know about the class of the object it segments?","o":["One of COCO’s 80 classes","One of ImageNet’s 1,000 classes","Whatever the prompt’s text says","Nothing: it outputs masks without classes"],"a":3,"w":"SAM is class-agnostic; to name the object, pair it with a classifier or an open-vocabulary detector."},{"n":25,"ti":"Foundation Models: SAM & Open-Vocabulary Detection","f":"25-sam-and-open-vocabulary.html","lv":"Advanced","q":"How does OWL-ViT decide that a box contains a “French horn”?","o":["It has a trained French-horn class","The box’s embedding is similar to the text embedding of the query","It reads the text in the image","It searches the web"],"a":1,"w":"The classifier is a set of text embeddings supplied at inference."},{"n":25,"ti":"Foundation Models: SAM & Open-Vocabulary Detection","f":"25-sam-and-open-vocabulary.html","lv":"Advanced","q":"For auto-labelling with SAM, which prompt is usually most reliable?","o":["A single click in the middle","A text prompt","A bounding box","No prompt at all"],"a":2,"w":"A box removes most of the ambiguity about the object’s extent; measured here it gave the highest mask IoU."},{"n":26,"ti":"Autoencoders & VAEs","f":"26-autoencoders-and-vaes.html","lv":"Advanced","q":"Why do random codes decoded by a plain autoencoder rarely look like images?","o":["The decoder is too small","The decoder was only trained on codes the encoder produced, which fill an irregular region with holes","The codes are too long","Autoencoders cannot use convolutions"],"a":1,"w":"Nothing in the reconstruction loss constrains what the decoder does away from training codes."},{"n":26,"ti":"Autoencoders & VAEs","f":"26-autoencoders-and-vaes.html","lv":"Advanced","q":"What does the reparameterisation trick do?","o":["It removes the KL term","It makes the encoder deterministic","It writes the sample as z = μ + σε with ε drawn separately, so gradients flow to μ and σ","It normalises the images"],"a":2,"w":"Sampling is moved outside the network; z becomes a differentiable function of the encoder’s outputs."},{"n":26,"ti":"Autoencoders & VAEs","f":"26-autoencoders-and-vaes.html","lv":"Advanced","q":"When is the KL term for one code dimension zero?","o":["When μ = 0 and σ = 1, so that dimension carries no information about the image","When σ = 0","When the reconstruction is perfect","Always, after training"],"a":0,"w":"½(μ² + σ² − log σ² − 1) is zero only at the prior; every bit of information a dimension carries costs KL."},{"n":26,"ti":"Autoencoders & VAEs","f":"26-autoencoders-and-vaes.html","lv":"Advanced","q":"What does raising β in a β-VAE do?","o":["Sharpens reconstructions","Makes training faster","Increases the code size","Pushes codes closer to N(0, 1): smoother sampling, worse reconstructions, fewer active dimensions"],"a":3,"w":"β prices information in the code; a high price means the model keeps less of it."},{"n":26,"ti":"Autoencoders & VAEs","f":"26-autoencoders-and-vaes.html","lv":"Advanced","q":"Why are VAE samples typically blurry?","o":["Because the images are only 32 × 32","An MSE decoder outputs the average of the images compatible with a code, and averages are blurry","Because of the sigmoid output","Because of batch normalisation"],"a":1,"w":"The same effect appears with no network at all: the pixel mean of an image’s nearest neighbours."},{"n":27,"ti":"Generative Adversarial Networks","f":"27-gans.html","lv":"Advanced","q":"How does the generator learn what real images look like?","o":["It is trained with pixel error against real images","It copies real images from the batch","Only through the gradient of the discriminator’s judgement of its outputs","It reads the labels"],"a":2,"w":"The generator never sees a real image; everything flows through D."},{"n":27,"ti":"Generative Adversarial Networks","f":"27-gans.html","lv":"Advanced","q":"Why is the non-saturating generator loss preferred over the minimax one?","o":["Early in training D rejects fakes easily, and log(1 − D) is flat there, so the minimax loss gives almost no gradient","It has a different equilibrium","It is faster to compute","It removes the need for a discriminator"],"a":0,"w":"Same fixed point, but −log D(G(z)) has a strong gradient precisely when the fakes are bad."},{"n":27,"ti":"Generative Adversarial Networks","f":"27-gans.html","lv":"Advanced","q":"What is mode collapse?","o":["The discriminator’s loss reaching zero","Training diverging to NaN","The generator producing blurry images","The generator covering only a few kinds of output, often cycling between them"],"a":3,"w":"It is a diversity failure: samples can be sharp but nearly identical."},{"n":27,"ti":"Generative Adversarial Networks","f":"27-gans.html","lv":"Advanced","q":"How does a minibatch standard deviation feature fight collapse?","o":["It normalises the generator","It lets the discriminator see how varied a batch is, so a low-diversity generator is easy to reject","It adds noise to real images","It increases the learning rate"],"a":1,"w":"A collapsed generator produces batches with almost no spread; D can now detect that directly."},{"n":27,"ti":"Generative Adversarial Networks","f":"27-gans.html","lv":"Advanced","q":"In a healthy GAN run, what do the two losses look like?","o":["Both fall steadily to zero","The discriminator’s loss reaches zero","They hover around a level as the two networks keep each other in check","The generator’s loss reaches zero"],"a":2,"w":"A loss at zero means one side has won, which usually means the generator has stopped learning."},{"n":28,"ti":"Diffusion Models from Scratch","f":"28-diffusion-from-scratch.html","lv":"Advanced","q":"What does the network in a DDPM predict during training?","o":["The clean image directly","The noise ε that was mixed into the image at a random timestep","Whether the image is real or fake","The timestep"],"a":1,"w":"ε-prediction with MSE; the timestep is given to the network, not predicted."},{"n":28,"ti":"Diffusion Models from Scratch","f":"28-diffusion-from-scratch.html","lv":"Advanced","q":"Why can training jump straight to any timestep instead of running the noising chain?","o":["Because the network is a U-Net","Because β is constant","Because the images are small","Gaussian noise steps compose into one Gaussian: x t = √ᾱ t x 0 + √(1 − ᾱ t ) ε"],"a":3,"w":"The closed form means one random t and one noise draw per image per step."},{"n":28,"ti":"Diffusion Models from Scratch","f":"28-diffusion-from-scratch.html","lv":"Advanced","q":"How is the timestep given to the denoising U-Net?","o":["As a sinusoidal embedding passed through an MLP and added in every residual block","As an extra image channel","It is not; the network infers it","As the batch size"],"a":0,"w":"Every block needs to know how much noise to expect."},{"n":28,"ti":"Diffusion Models from Scratch","f":"28-diffusion-from-scratch.html","lv":"Advanced","q":"What does DDIM change compared with DDPM sampling?","o":["It retrains the network","It uses a different noise schedule for training","It uses the same network with a deterministic update that can skip many timesteps","It removes the U-Net"],"a":2,"w":"Estimate x̂ 0 from the predicted noise, then jump to a much lower noise level."},{"n":28,"ti":"Diffusion Models from Scratch","f":"28-diffusion-from-scratch.html","lv":"Advanced","q":"Why is GroupNorm used instead of BatchNorm in the denoiser?","o":["It is faster","Images in one batch are at different noise levels, so batch statistics mix very different inputs","BatchNorm cannot be used with attention","GroupNorm has more parameters"],"a":1,"w":"Per-sample normalisation keeps each image’s statistics separate."},{"n":40,"ti":"The CV Interview Playbook","f":"40-interview-playbook.html","lv":"Expert","q":"What is the output size of a 3 × 3 convolution with stride 2 and padding 1 on a 56 × 56 input?","o":["27","28","29","56"],"a":1,"w":"(56 + 2 − 2 − 1) // 2 + 1 = 27 + 1 = 28."},{"n":40,"ti":"The CV Interview Playbook","f":"40-interview-playbook.html","lv":"Expert","q":"How many parameters does a 3 × 3 convolution from 64 to 128 channels have, without bias?","o":["1,152","8,192","36,864","73,728"],"a":3,"w":"128 × 64 × 3 × 3. Forgetting the 64 input channels gives 1,152."},{"n":40,"ti":"The CV Interview Playbook","f":"40-interview-playbook.html","lv":"Expert","q":"How many tokens does ViT-B/16 process for a 384 × 384 image?","o":["577","197","576","1,025"],"a":0,"w":"(384/16)² = 576 patches plus the class token = 577; at 224 it is 197."},{"n":40,"ti":"The CV Interview Playbook","f":"40-interview-playbook.html","lv":"Expert","q":"In a debugging round, what should usually come before retraining?","o":["Trying a bigger model","Collecting more data","Checking the inputs the model actually receives, and its mode","Changing the loss"],"a":2,"w":"Pipeline bugs (channel order, normalisation, eval mode, orientation) are common, cheap to test and invisible to retraining."},{"n":40,"ti":"The CV Interview Playbook","f":"40-interview-playbook.html","lv":"Expert","q":"What should the first minutes of a design round be spent on?","o":["Choosing the backbone","Requirements: the task, the metric, latency, hardware and labels","Writing the training loop","Drawing the network"],"a":1,"w":"Requirements decide the model, the data and the evaluation. A design without a metric cannot be judged."}];
